window.TEXT3_DATA = {"2010-07": [{"head": "留守番電話のメッセージを聞いています。", "lines": [{"k": "spk", "s": "女", "t": "田中です、明日のことでお電話したんですけど。あのう、大変申し訳ないんですが、父がちょっと具合が悪くなりまして、あっ、父は今大阪にいるんですけど、姉が大阪に行くことになったんです。それで、姉の子供たちの面倒を私が見ることになりまして、大変申し訳ないんですが、明日のお約束別の日にしていただければと思いまして、またこちらからお電話いたします。失礼します。"}, {"k": "q", "t": "留守番電話の内容はどのようなことですか。"}, {"k": "ch", "t": "1.子供の世話をしてほしい"}, {"k": "ch", "t": "2.約束を変更したい。"}, {"k": "ch", "t": "3.一緒に大阪に行きたい"}, {"k": "ch", "t": "4.会う場所を決めたい。"}]}, {"head": "テレビで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "母がピアノの先生だったので、子どものころから、楽器や歌を習ったりしていました。でも、父は普通の会社員でしたし、女優になるなんて、夢にも思っていませんでした。大学のときの友達に演劇に夢中の子がいて、一緒によく劇を見に行っていたんですが、あるとき、彼女の所属する劇団で、頼まれて、ちょっとした役をやったんです。それをある映画監督がたまたま見ていて、声をかけてくださったんです。それで、この道に入りました女の人の話のテーマは何ですか。"}, {"k": "ch", "t": "1.子どもの頃の思い出"}, {"k": "ch", "t": "2.大学時代の友人との思い出"}, {"k": "ch", "t": "3.女優になったきっかけ"}, {"k": "ch", "t": "4.映画監督になったきっかけ"}]}, {"head": "食品会社の社長がラジオで話しています。", "lines": [{"k": "spk", "s": "男", "t": "最近は食べ物にいろいろな工夫がされていて、においが強いものや、酸つばすぎたり、辛すぎたりする物は子どもや若い人でも食べやすいように変えて売られているようです。一方、昔からの味が懐かしいという方からの意見も多く、わが社では、味を伝えることは文化を伝えること、と考え、子どものころに食べた味を思い出すような商品を作るようにしています。"}, {"k": "q", "t": "社長は自分の会社の商品についてどう考えていますか。"}, {"k": "ch", "t": "1.いままでにない味を開発したい"}, {"k": "ch", "t": "2.昔からの味を大切にしたい。"}, {"k": "ch", "t": "3.若い人向けの商品を作りたい。"}, {"k": "ch", "t": "4.刺激の少ない商品を作りたい。"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "最近見本でよく使われているものに、リネンという布があります。リネンは丈夫で肌にもやさしい性質のため、昔からいろいろなものに利用されてきました。代表的なものに、シーツや枕カバーと言った寝具、タオル、食事用のナプキンなどがあります。また、西洋では古くからリネン素材で下着を作ってきました。最近、日本でもリネン素材が婦人服にも使われるようになっています。リネンはさまざまな製品に形を変え、人々の暮らしに役立っているのです先生はどのようなテーマで話していますか。"}, {"k": "ch", "t": "1.リネンの作り方"}, {"k": "ch", "t": "2.リネンの性質"}, {"k": "ch", "t": "3.リネンの使われ方"}, {"k": "ch", "t": "4.リネンの流行"}]}, {"head": "大学の卒業式で学長が話しています。", "lines": [{"k": "spk", "s": "男", "t": "これから社会に出て行くみなさんは、諸先輩方から社会人としての自覚と責任をもとう、時間を守るのが、社会人のルールだ、などいろいろな助言を受けていることと思います。和は皆さんにはせひ強い心を持った人になってほしいと思います。本当に強い人というのは他人にやさしくできるものです。困難の多いこんな時代だからこそ、人と争うのではなく、人をいたわることのできる、人の痛みのわかる人間になってほしいと願っています。"}, {"k": "q", "t": "学長が言いたいのはどのようなことですか。"}, {"k": "ch", "t": "1.社会人としての責任感を持ってほしい"}, {"k": "ch", "t": "2.社会のルールを守る人になってほしい"}, {"k": "ch", "t": "3.意志を曲げない強い人になってほしい"}, {"k": "ch", "t": "4.思いやりの心を持ってほしい"}]}, {"head": "テレビで女の人が話しています", "lines": [{"k": "spk", "s": "女", "t": "最近、青少年の犯罪のニュースが急増しています。子どもを取り巻く環境の変化も一因として考えられるでしょう。では、今後、どのように対策を講じたらよいのでしょうか。日本には犯罪を犯した未成年者を保護する法律がありますが、たとえ未成年者といえども、犯した罪の重さは同じだという考え方もあります。私は個人的には犯した罪の責任を取らせるようにしないかぎりは、このような犯罪は減らないんじゃないかと思っています。こういうことをしたらこういう罰があるということを毅然とした態度で示す必要があるのではないでしょうか。"}, {"k": "q", "t": "女の人の話しのテーマは何ですか。"}, {"k": "ch", "t": "1.子どもを取り巻く環境の変化"}, {"k": "ch", "t": "2.子供に対して親がとるべき態度"}, {"k": "ch", "t": "3.青少年による犯罪の増加"}, {"k": "ch", "t": "4.青少年の犯罪への対応策"}]}], "2010-12": [{"head": "ボランティアグループの会長が話しています。", "lines": [{"k": "spk", "s": "女", "t": "私はこのボランティアグループの会長しています。私たちのグループは10年くらい前に5人の学生がボランティアサークルとして活動したのが始まりです。発足当時は迸隣の小学校や病院に行って活動していたのですが、その後地域の方と協力するようになり、実績を積んできました。市から依頼を受けるようになったのを機により規模の大きい活動をするようになり、今に至っているというわけです。"}, {"k": "q", "t": "会長の話のテーマは何ですか。"}, {"k": "ch", "t": "1.グループの目的"}, {"k": "ch", "t": "2.グループの歴史"}, {"k": "ch", "t": "3.グループのメンバー"}, {"k": "ch", "t": "4.グループの現在の活動内容"}]}, {"head": "テレビで栄養学の専門家が話しています。", "lines": [{"k": "spk", "s": "女", "t": "コーヒーは体に悪いというイメージを持つ人もいるようですが、病気を予房する効果もあることが報告されています。ええ、ある調査てはコーヒーを一日三倍以上飲む人は、糖尿病を発症する可能性が、ほとんど飲まない人より40パーセント少ないという結果が出ています。癌や心臓病の予防にも効果があるという報告もあります。コーヒーを飲むと胃が荒れるという話があるかもしれませんが、それは過剰な摂取によるものと思われます。まあ、コーヒーに限らずなんでも過剰な摂取はよくありません。"}, {"k": "q", "t": "この専門家は何の話をしていますか。"}, {"k": "ch", "t": "1.コーヒーを飲む人の割合"}, {"k": "ch", "t": "2.コーヒーの効果"}, {"k": "ch", "t": "3.コーヒーの成分"}, {"k": "ch", "t": "4.コーヒーの消費量"}]}, {"head": "留守番電話のメッセージを聞いています。", "lines": [{"k": "spk", "s": "男", "t": "お世話になっております。朝日商事の佐藤ですあの、先日ご注文いただいた商品の件なんですが、こ依頼の100個は入手できませんでしたが、80個はなんとか確保いたしました。で、この80個でよろしいかどうか、お教えください。商品の価格はご希望の範囲に抑えられそうですし、お届けの日も先日お伝えしたとおりで変更はありません。後ほどこちらからお電話いたしますので、ご指示お願いいたします。それでは失礼致します。"}, {"k": "q", "t": "何についてのメッセージですか。"}, {"k": "ch", "t": "1.商品の数の確認"}, {"k": "ch", "t": "2.価格の交渉"}, {"k": "ch", "t": "3.配達日の変更"}, {"k": "ch", "t": "4.注文方法の変更"}]}, {"head": "テレビで作家がインタビューに答えます。", "lines": [{"k": "spk", "s": "女", "t": "先生は世界各地を回られて旅行の本をたくさん書かれていますが、海外旅行を計画している人たちに一言お願いします。"}, {"k": "spk", "s": "男", "t": "そうですね、有名な遺跡などに行く人も多いと思うんですが、僕は誰も住んでいない遺跡を目の前にしても自分の部屋でガイドブックを眺めているような感じを受けてしまうんです。普通の人が暮らす町に行ったほうが異国へ来たことを肌で感じることが出来ます人々が住んでいるところを散策してみてはどうでしょうか。生活から生まれる音やざわめき匂い、そういうものほど五感を刺激するものはないと思うんです。これはその国の歴史を学ぶだけでは得られないものです。"}, {"k": "q", "t": "作家が伝えたいことは何ですか。"}, {"k": "ch", "t": "1.旅行の本を読んでおいた方がいい"}, {"k": "ch", "t": "2.遺跡を訪れた方がいい"}, {"k": "ch", "t": "3.人々の生活に触れた方がいい。"}, {"k": "ch", "t": "4.その国の歴史を学ぶべきだ"}]}, {"head": "社長が新入社員に話しています。", "lines": [{"k": "spk", "s": "男", "t": "新入社員の皆さん、皆さんは昨今の競争社会を生き抜くためには誰にも負けない何かを一っ持っていることが大切だと思っているかもしれません。ですが、この不諸かな時代いっどんな経験がどんな場面で役立つかは誰にもわかりません。ですから始めから一つのことダくさくに的を絞るのは視野が狭くなり得策とは言えないでしょう。自分には専門外だと思ってもそれに全力で取り組みその経験を重ねていくことは後々その人の宝になります。何事にも釚戦する気持ちを忘れず、自分に向いていないと思ったことにも前向きに取り組んでいくことが肝要だと考えます。"}, {"k": "q", "t": "社長が伝えたいことは何ですか。"}, {"k": "ch", "t": "1.得意分野を持ってほしい。"}, {"k": "ch", "t": "2.さまざまな経験をつんでほしい。"}, {"k": "ch", "t": "3.自分の専門をいかしてほしい。"}, {"k": "ch", "t": "4.競争心を持ってほしい。"}]}], "2011-07": [{"head": "テレビでレポーターが話しています。", "lines": [{"k": "spk", "s": "女", "t": "はい。こちら、レポーターの山本です。今、私が来ているこの地域には、桜歌舞伎という伝統芸能があります。300年以上の歴史があり、長く人々に親しまれてきたのですが、実は、この伝統芸能、後継者不足で、一度存続が危ぶまれたことがあるんです。そのとき立ち上がったのが、なんと、この町の高校に通う高校生たちだったのです。伝統芸能を継承し、歴史を受け続いでいこうと、放課後、練習を重ねています。伝統芸能の衰退が珍しくない中で、この高校生の奮闘ぶりに、町でも、これが町の活性化に繋がらないか考え始めたようです。"}, {"k": "q", "t": "レポーターは主に何について伝えていますか。"}, {"k": "ch", "t": "1.伝統芸能の魅力"}, {"k": "ch", "t": "2.伝統芸能の継承"}, {"k": "ch", "t": "3.地域の歴史"}, {"k": "ch", "t": "4.地域の活性化"}]}, {"head": "大学で先生がある国について話しています。", "lines": [{"k": "spk", "s": "男", "t": "この国は、今、経済の転換期を迎えています。この国の経済発展を支えているのは、地下に埋蔵されている豊富な天然資源です。しかし、埋蔵されている資源には限りがあります。また、このまま資源の輸出だけに依存していると、資源価格の変動によって、経済情勢が大きく左右されてしまいます。そこで政府は、資源の輸出で得られた豊富な外貨をもとに、新しい産業を育成する計画を立てています。"}, {"k": "q", "t": "先生はこの国の何について話していますか。"}, {"k": "ch", "t": "1.今後の経済政策"}, {"k": "ch", "t": "2.資源価格の変動"}, {"k": "ch", "t": "3.地下資源の埋蔵量"}, {"k": "ch", "t": "4.資源の輸出促進"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "私たちの周りには、毎日、いろんな音が溢れていますが、スーパーや飲食店に行ったとき、店の中に流れている音楽を意識したことがありますか~ほとんどの人は特に気にしていないと思います。ある調査によると、ゆっくりした音楽を流した場合と、テンポの速い音楽を流した場合とでは、客の行動に差があることがわかりました。スーパーなどでは、ゆっくりした音楽を流したときのほうが、客が店の中にいる時間が長くなり、売上が伸びるんだそうです。反対に、行列ができるような混んでいる飲食店では、テンポの速い音楽を流すことで、客の回転を速くすることができるんだそうです。"}, {"k": "q", "t": "男の人はどのようなテーマで話をしていますか。"}, {"k": "ch", "t": "1.生活の中の騒音"}, {"k": "ch", "t": "2.騒音と音楽の違い"}, {"k": "ch", "t": "3.音楽と客の行動の関係"}, {"k": "ch", "t": "4.店の雰囲気と音楽"}]}, {"head": "テレビで農業の専門家がキノコについて話しています。", "lines": [{"k": "spk", "s": "女", "t": "キノコにはたくさんの種類がありますが、今日はその代表格であるシイタケについてお話ししたいと思います。シイタケは炒め物や鍋物など、様々な料理に使われていますが、どのように栽培するかは、あまり知られていないかもしれません。質の良いシイタケを収穫するには木を使う方法が良いでしょう。えー、シイタケはシイタケ菌を木に植えつけ、乾燥を避け、十分な湿度を保っと生えてきます。生育には10度から30度の間を保つことが必要とされるので、春か秋が適した季節と言えます。生えてから2週間程度で収穫できる大きさになるでしょう専門家の話のテーマはなんですか。"}, {"k": "ch", "t": "1.質のいいシイタケの選び方"}, {"k": "ch", "t": "2.シイタケの育て方"}, {"k": "ch", "t": "3.シイタケの調理方法"}, {"k": "ch", "t": "4.シイタケの保存方法"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、今日は初回なので、今学期の授業内容について簡単に説明します。この授業では最新の科学技術に注目します。と言っても、科学技術を難しくとらえるのではなく、生活の中でどのように役立っているか見ていきます。例えば、最近ニュースなどで高齢化社会の問題が取り上げられていますね。日本の場合、2055年には65歳以上の高齢者が人口の40を超えると予測されていますが、その時に、介護や福祉を担う労働力をどう確保するかが問題です。えー、そこで、高齢者の暮らしを支えると期待されているのが現在開発中の介護ロボットです。最新の科学技術は、私たちの生活に深く結びついているのです。えー、では今日は、のようなロボットに使われている技術について見てみたいと思います。"}, {"k": "q", "t": "今学期の授業のテーマはどのようなことですか。"}, {"k": "ch", "t": "1.科学の最新理論"}, {"k": "ch", "t": "2.生活に役立っ科学技術"}, {"k": "ch", "t": "3.高齢化社会の問題"}, {"k": "ch", "t": "4.介護ロボットの開発の課題"}]}, {"head": "会議で女の人が男の人に意見を聞いています。", "lines": [{"k": "spk", "s": "女", "t": "では、新しい店舗の設置とメニュー価格の値上げについてご意見をお願いします。"}, {"k": "spk", "s": "男", "t": "まず、新店舗の設置についてですが、私は積極的に行くべきだと考えます。この地区には競合するレストランがいくつもあるので、避けたほうがいいという考え方もできると思いますが、駅前の開発事業なども進んでいますので、メニューやサービスで差別化を図れば、お客の獲得は見込める地域だと考えます。で、もうーっの議題の、コストの上昇によるメニュー価格の値上げについては、昨今の景気の動向を考慮すれば、むしろ価格を抑えて、ほかの会社の店舗との差別化を図るべきだと思います。"}, {"k": "q", "t": "男の人はどう考えていますか。"}, {"k": "ch", "t": "1.店舗の新設にも値上げには賛成"}, {"k": "ch", "t": "2.店舗の新設にも値上げにも反対。"}, {"k": "ch", "t": "3.店舗の新設は賛成、値上げは反対。"}, {"k": "ch", "t": "4.店舗の新設は反対、値上げは賛成。"}]}], "2011-12": [{"head": "ラジオのニュースでアナウンサーが社会人の進学について話しています。", "lines": [{"k": "spk", "s": "男", "t": "社会に出た後で、大学院に進学する人が増加傾向にあります。学問を追求することを目的とする人もいれば、資格取得を目指す人もいます。中でも、専門的な知識を身につけて、転職をしたり、会社を立ち上げたりする、という目標を持つ人が目立ちます。社会的には、雇用が減っているなどの経済的な問題や、より高度なキャリアを要求する時代的背景があるようです。また、少子化の影響を受け、学生数を確保したいという大学側の狙いもあるということですアナウンサーは社会人の進学について、何を話していますか。"}, {"k": "ch", "t": "1.進学する人が増えている理由"}, {"k": "ch", "t": "2.進学に必要な資格"}, {"k": "ch", "t": "3.進学が大学に与える影響"}, {"k": "ch", "t": "4.進学のための経済的支援"}]}, {"head": "講演会で男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、私は紙創りの仕事をしています。紙は紙でも、日本の伝統的な紙、和紙です。和紙には、独特の柔らかい質感があって、手に取るとなんとも言えない暖かさを感じます。保存性も非常に高いんで、長く使い続けることができます。原料は主に、(こうぞ)っていう、メートルから五メートルぐらいの高さの木です。この木は、二酸化炭素の吸収が良く、早く大きくなるので、効率的に栽培できるんです。それに、和紙は科学的な薬品も大掛かりな機械も使わずに作ることができて、非常に環境にやさしいんですね。こういったことも和紙の価値を高めていると思います。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.和紙の種類"}, {"k": "ch", "t": "2.和紙の魅力"}, {"k": "ch", "t": "3.和紙の使われ方"}, {"k": "ch", "t": "4.和紙を作る技術"}]}, {"head": "ラジオの育児相談の番組で、専門家が話しています。", "lines": [{"k": "spk", "s": "女", "t": "チョコレート、飴、アイスクリーム、子供は甘いおやつが大好きです。子供は一回の食事の量が少ないので、おやつは栄養面からいっても必要ですが、甘いおやつは虫歯の原因にもなります。甘いものを食べた後に歯磨きの習慣がつけばいいんですが、子供は親の思うように歯磨きをしてくれません。子供に歯磨きの習慣をつけさせたいばかりに、親がストレスを感じてもよくありません。そこでおすすめなのが、甘いものを食べた後に、水やお茶を飲む習慣をつけることです。甘いものを食べると、口の中の酸性度が高まって、歯に悪い影響を与えます。歯の衛生面からいって完璧ではありませんが、水やお茶やその酸性度を下げる働きがあります。"}, {"k": "q", "t": "専門家は主に何について話していますか。"}, {"k": "ch", "t": "1.子供のおやっ必要性"}, {"k": "ch", "t": "2.正しい歯磨きの仕方"}, {"k": "ch", "t": "3.育児ストレスの対処法"}, {"k": "ch", "t": "4.子供の虫歯の予防法"}]}, {"head": "大学で先生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、二十二世紀までに起りうる問題は多岐にわたっていますが、まず、人口増加について考えましょう。まあ、一部の国では、少子化によって、人口が減少してますが、ああ、地球規模では著しい増加を続けていると言えます。人口が増えた場合、一番に考えられる問題はですね、食料危機です。食糧の不足は、社会全体に混乱を招く恐れがあるんです。次にもうーっ起ってくるのが住宅不足ですね。住むところを確保するために、自然環境はますます破壊されていくでしょう。それにですね、人口が増えても、それに見合った雇用が生まれるとは限りませんし、深刻な失業率の上昇が社会問題化することも考えられます。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.人口増加が招く問題"}, {"k": "ch", "t": "2.食糧不足の解決法"}, {"k": "ch", "t": "3.少子化と雇用問題の関係"}, {"k": "ch", "t": "4.人口が増えている原因"}]}, {"head": "テレビで、男のアナウンサーと経済の専門家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "高齢化が進み、医療や年金など、国の支出が増えており、それを補うために、消費税をあげることが議論されています。消費税が上がった場合、私たちの生活はどうなっていくのでしょうカ)。"}, {"k": "spk", "s": "女", "t": "そうですね、現在は食品などの生活必需品から、高級車や宝石などの贅沢品まで、すべてのものに対して同じ税率が課せられています。このままでさらに税率をあげると、低取得者層の負担が相対的に増えると考えられます。"}, {"k": "spk", "s": "男", "t": "それは、どういうことですか。"}, {"k": "spk", "s": "女", "t": "ええ、所得にかかわらず、食品などの生活必需品には一定のお金がかかります。ということは、低所得者のほうが、収入に占める消費の割合は高いんです。すべてのもので、一律に消費税を増税することになれば、結果的に、低取得者の相対的な負担がますます大きくなることになります。"}, {"k": "spk", "s": "男", "t": "そうですか。それは大きな問題ですね。"}, {"k": "spk", "s": "女", "t": "はい。福祉を充実させるために消費税をあげることはやむを得ないかもしれませんが、低取得者層の負担を軽減するためには、従来の方法については見直すべきでしょう。"}, {"k": "q", "t": "専門家は消費税についてどう考えていますか。"}, {"k": "ch", "t": "1.税率を上げるべきではない。"}, {"k": "ch", "t": "2.税率はすべてのもので同じにするべきだ"}, {"k": "ch", "t": "3.税率は物によって差をつけるべきだ。"}, {"k": "ch", "t": "4.税率は所得によって差をつけるべきだ"}]}, {"head": "テレビで女のアナウンサーと映画監督が話しています。", "lines": [{"k": "spk", "s": "女", "t": "今回の映画を拝見して感じたことなんですが。映画の中で使わている日常の生活音がとても印象的でした"}, {"k": "spk", "s": "男", "t": "はい、その点は全体を通してこだわったところです。僕もこの映画の主人公のように十八のときに田舎から東京に出てきたんですけど。はじめて家族から離れて周りに誰しやべる人がいない寂しさに襲われたんです。そんなとき、近所の人たちの笑い声や、子どもの遊んでいる声とかに、すごく癒されたんですよ。"}, {"k": "spk", "s": "女", "t": "都会で一人暮らしをしていると、どうしても孤独になりがちですよね。"}, {"k": "spk", "s": "男", "t": "そうなんです。そういう時に聞こえてくる人の血が通った音っていうのは、聞く側を癒してくる力があると思うんです。"}, {"k": "spk", "s": "女", "t": "一方で、現実では、隣の家の騒音がトラブルになることもありますよね。"}, {"k": "spk", "s": "男", "t": "ええ、自分の気持ちが落ち込んでるときは、隣から聞こえてくる掃除機の音とか、うるさいなあと思うこともあります。たから、意図的にそういうシーンも入れました。"}, {"k": "spk", "s": "女", "t": "それはまたリアルで、生きている人間がうまく表現されているところですね。"}, {"k": "spk", "s": "男", "t": "そう評価していただいて、ありがたいです。生活音なんて、些細なものだけど、それによって人と人が繋がっているんですよね。まあ、この映画を見終わった後、音の先に誰かが生きているんだなあと、なんとなく感じてもらえたら、それで満足です。"}, {"k": "q", "t": "映画監督は何について話していますか。"}, {"k": "ch", "t": "1.映画の効果音の作り方"}, {"k": "ch", "t": "2.映画作りでこだわったところ"}, {"k": "ch", "t": "3.登場人物の人間関係"}, {"k": "ch", "t": "4.映画のあらすじ"}]}], "2012-07": [{"head": "電気屋の店員が新しい掃除機について説明しています。", "lines": [{"k": "spk", "s": "店員", "t": "えー、'の掃除機は騒音が小さく、テレビを見ている部屋で使っても邪になりません。それにとても軽く、階段でも楽に持ち運べます。さらに、この商品の一番素晴らしい点はですね、部屋の空気を汚さないことです。汚れは掃除機の中でこのようにゴミときれいな空気に分けられ、外には綺麗な空気しか出ていきません。うーん、今までのものより価格は少し高めですが、赤ちゃんがいるご家庭にもぜひおすすめしたい商品です。電気屋の店員は主に何について話していましたか。"}, {"k": "ch", "t": "1.掃除機の性能"}, {"k": "ch", "t": "2.掃除機の価格"}, {"k": "ch", "t": "3.掃除機の使い方"}, {"k": "ch", "t": "4.掃除機を買う人"}]}, {"head": "男の学生が女の学生に電話をかけています。", "lines": [{"k": "spk", "s": "男", "t": "もしもし、高橋だけど、今いい~"}, {"k": "spk", "s": "女", "t": "うん。何~"}, {"k": "spk", "s": "男", "t": "あのさ、俺、コンビニでバイトやってるのを知ってるよね。最近卒業でやめる人が多くてね。人手足りなくて困ってるんだよ。俺も最近授業のレポートとかで忙しいし。"}, {"k": "spk", "s": "女", "t": "レポートならいつも手伝ってあげてるでしょう~"}, {"k": "spk", "s": "男", "t": "あ、それは感謝していますよ。"}, {"k": "spk", "s": "女", "t": "あっ、そう~"}, {"k": "spk", "s": "男", "t": "で、もうすぐ四年だから、仕事探さなきゃならないし、これ以上バイトいれらんないんだよね。で、店長が誰かいないかって探してんだよ。"}, {"k": "spk", "s": "女", "t": "えー私、もう目一杯バイトしてるからね。"}, {"k": "spk", "s": "男", "t": "うん、それは分かってる。じゃなくて、心当たりないかな"}, {"k": "spk", "s": "女", "t": "ふうん。分かった。じゃ、ちょっと考えてみるね男の学生は女の学生に何を頼んでいますか。"}, {"k": "ch", "t": "1.レポートを手伝ってほしい"}, {"k": "ch", "t": "2.新しい仕事を紹介してほしい"}, {"k": "ch", "t": "3.アルバイトをしてほしい。"}, {"k": "ch", "t": "4.アルバイトができる人を紹介してほしい。"}]}, {"head": "ラジオを聞いています。", "lines": [{"k": "spk", "s": "男", "t": "こんにちは、ふじ町夏祭り実行委員会からのお知らせです。八月八日から十日まで恒例の夏祭りが開徹されます。今年は五十周年に当たるため、花火大会も同時開催され、例年を上回る来場者数が見込まれます。そこで、夏祭り開催中来場される方々に気持ち良く過ごしていただくため、ボランティアによる清掃活動を行いたいと思います。時間は午前七時より約一時間程度で、集合場所は中央公園の駐車場です。皆様、是非ご協力くださいますよう、お願い申し上げます。"}, {"k": "q", "t": "男の人は何を呼びかけていますか。"}, {"k": "ch", "t": "1.夏祭りへの参加"}, {"k": "ch", "t": "2.実行委員会への参加"}, {"k": "ch", "t": "3.花火大会への参加"}, {"k": "ch", "t": "4.清掃ボランティアへの参加"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "先生", "t": "都市部は地面がアスファルトで覆われていますから、雨水は地面に染み込まないで、下水道に流れるようになっています。ところが、近年、増加している集中豪雨では想定を超える量の雨水が一気に下水に流れ込むために、あふれ出してしまいます。これが都市部で浸水の被害が起こる原因です。で、その対策として、地上にタンクを設置する取り込みが広がっています。タンクに雨水を貯めることで下水道の負担を減らし、被害を抑えます。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.集中豪雨が起こる理由"}, {"k": "ch", "t": "2.雨水を下水道に流す仕組み"}, {"k": "ch", "t": "3.浸水被害の原因と対策"}, {"k": "ch", "t": "4.雨水を利用する取組み"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "みなさん、こんにちは、お昼の一時、如何お過ごしですか。今日は私の学生時代の話をしたいと思うんですけど。私学生時代、バスケットボールをやってたんですね。で、ある日、大阪出身の先輩に、これ直しといてってポールを渡されたことがあったんです。あ、私生まれも育ちも東京なんですけどね。で、私、ポールを見ながら、修理するところなんかないのにおかしいなあって思ってたんですよ。そうしたら、先輩に「あ、こめん。分からなかったよね。片付けておいてって意味だったの」って言われて、びつくりしたことがありました。私は引っ越した経験もないので、本当びつくりしました。みなさんもこんな経験ありませんか女の人は主に何について話していますか。"}, {"k": "ch", "t": "1.バスケットボールの練習"}, {"k": "ch", "t": "2.ポールの修理方法"}, {"k": "ch", "t": "3.言葉の地域差"}, {"k": "ch", "t": "4.先輩に対する言葉遣い"}]}, {"head": "テレビで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "えー、最近こうして農業の楽しさや失敗談なんかをお話しする機会が増えたのですが、実は私も農家としてはまだまだかけだしです。10年前までは、ごく普通のOLでした。そんな私が農業に目覚めたのは子供の存在が大きいです。子育てをするようになったら、子供のロに入るものが気になってきたんですね。例えば、野菜ーっ取っても、生産階段でどんな農薬が使われているか、正確には分かりませんよね。でも、親としては、やつばり安全なものを子供に食べさせたいと思ったんです。それで、じや自分でできる限り安全なものを作ろうって思って、この世界に入りました女の人は何について話していますか。"}, {"k": "ch", "t": "1.農業の楽しさや失敗"}, {"k": "ch", "t": "2.子育てと農業の両立"}, {"k": "ch", "t": "3.農薬を使わない農業"}, {"k": "ch", "t": "4.農業を始めた理由"}]}], "2012-12": [{"head": "会社の会議で男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "昨日午後四時十分、当社のオンラインショップがダウンしました、原因は新たに取り扱いを始めた有名店の限定チョコレートの販売開始直後、予想以上の人気で、処理能力を超えるアクセスが集吊したためです。通常、お客様は商品を選択した後、配送先を指定するのですが、この配送先の画面にアクセスできない。または、画面が表示されるまでに時間がかかるなどの障害が発生しました。五時半には復旧しましたが、これまでに50件強の古情がありました。幸い、注文件数には大きな影響はありませんでしたが、販売方法の改善が必要かどうかについては現在封中です。"}, {"k": "q", "t": "問い男の人はオンラインショップの何について報告していますか。"}, {"k": "text", "t": "1売り上げが下がったこと。2販売システムで問題が起きたこと。3取り扱い商品の在庫が不足したこと。4配方法の改善が必要なこと。"}]}, {"head": "駅前で市議会議員が演説をしています。", "lines": [{"k": "spk", "s": "男", "t": "皆さん、佐倉市の公園についてどのようにお考えでしょうか。緑ある公園は子供の健全な遊び場、市民の憩いの場として必要不可欠です。町の中に緑を配置することで生活も潤います。これらは小規模公園でも賄うことができますが、都市環境の向上を考えた場合、小学校の校庭程度の大規模公園が必要です。大規模公園はそれだけではなく、災害時の避難場所として、また、町の資産価値を高めるためにも欠かすことはできないのです。しかし、残念ながら、わが往倉市にはこのような役割を担う公園がありません。駅前の工場跡地は絶好の場所だと考えます"}, {"k": "q", "t": "問い議員は何を主張していますか。"}, {"k": "text", "t": "1今ある公園の価値を高めること。2小さい公園を増やすこと。3大きい公園を作ること。4小学校の校庭を広くすること。"}]}, {"head": "講演会で女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "これは私の知人のアメリカ人の話なんですが、彼はラジオを聞いて、あの司会者はいい人だとか、このタレントは美しい日本語を話すとか言って、何人かの話し手をひいきにしています。ところが、実は日本語がほとんどわからないんです。通常私たちが誰かの話を聞くときは、相手が話したことの意味を把握することに集中しますが、単語や文法から意味を見いだせない彼にしてみれば、話す声こそが唯一の情報源なのです。そして、これは話されている内容を普段、私達が単語とか文法から考えてしまい、話している声に含まれている情報をあまり意識していないということを、改めて考えさせてくれているように思えます。"}, {"k": "q", "t": "問い女の人は何について話していますか。"}, {"k": "text", "t": "1声の出し方と職業の関係。2声が持つ情報の大切さ。3美しい言楽遣いの必要性4発言内容を理解することの重要性。"}]}, {"head": "新商品の企画会議で、部長が話しています。", "lines": [{"k": "spk", "s": "男", "t": "売れる商品を開発するにはね、経験とか技術力とか、そういったものだけじゃ十分じゃないんだよ。いい商品が生み出せるかどうかは、お客様をいかによく見ているかってことにかかってるといっても過言じゃない。ええ、例えば、印鑑やスタンプ、これにはどっちが上か目印がついてるけど、もし目印がなかったら、印鑑を押す時、向きがわかんないでしょう。これはほとんどの人が印鑑やスタンプを押す時、必ず向きを確かめるっていう行動を見て開発したそうなんだ。こんなとこに開発のヒントは転がってるんだよ。つねにこういう視熹を頭に置いて、商品開発ってのをすすめていきたいよね"}, {"k": "q", "t": "問い部長は何について話していますか。"}, {"k": "text", "t": "1消費者の意見を聞くことの大切さ。2商品開発の経験を積むことの大切さ。3技術力を上げることの大切さ4消費者の行動を観察することの大切さ。"}]}, {"head": "テレビで女のアナウンサーが会社の経営について社長にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "今日は、株式会紅コヤマの小山紅長にお越しいただき、お話を伺います。社長、よろしくお願い致します"}, {"k": "spk", "s": "男", "t": "こちらこそ、よろしくお願い致します。"}, {"k": "spk", "s": "女", "t": "社長は大学を卒業すると同時に、この会社を立ち上げられたそうですね。この不況の中でも、売上げをどんどん伸ばしていらっしゃいますが、会社が成功するためには、何が必要なんでしょうか。"}, {"k": "spk", "s": "男", "t": "そうですね。チャンスを逃さない努力といったところでしょうか。こう言うと、よく誤解されるのですが、チャンスがあれば、思い切って突っ走れと言っているのではありません。何がチャンスであるかをしつかりと見極め、実行に移すべきか、的確に判断しなければならず、そのためには、日頃から、つねに情報を収集、分析する必要があるのです。また、リスクもしつかりと考慮しなければなりません。"}, {"k": "spk", "s": "女", "t": "なるほど。日頃から、努力されているんですね。"}, {"k": "spk", "s": "男", "t": "念入りの調査に基づいて、現状を客観的に見ることが出来れば、大きなチャンスをものにできるのです。思いっきと思い切りのよさだけでは、会社の経営というものはいずれ行き詰まるのではないでしょうか。もちろん、条件によっては、どんなにすばらしいアイデアでも実行に移さないという決断をすることもあります。そういう意味での思い切りのよさは必要かもしれませんね。"}, {"k": "q", "t": "問い社長は会社の経営について、何が重要だと言っていますか。"}, {"k": "text", "t": "1失敗を恐れないこと。2状況を客観的に分析すること。3すばやく決断すること。4いいアイディアを生み出すこと。"}]}], "2013-07": [{"head": "ラジオで女のアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "せつかく買った植物を出張や旅行で留守にした際に、枯らしてしまったという話を聞きます。留守中に耒の世話を頼めるような近所付き合いがあるに越したことはないのですが、なかなかそうも行きませんよね。留守がちだから、ペットどころか、植物もだめ。そんな都会人の悩みを解消しようと、ある園芸店がプラントシッターという新たなサービスを始めました。ペットを預かるように、植物を預かったり、客の家まで水やりに行くというものです。私が知っている限り、園芸店でこのような取り組みをしている店はほかにありまきやくかくダくつなせん。専門店ならではの細やかな対応で、新しい顧客獲得に繋げていきたいと意気込んでいます女のアナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.植物を育てることの難しさ"}, {"k": "ch", "t": "2.ペットが飼えない往宅情"}, {"k": "ch", "t": "3.都会の人間関係"}, {"k": "ch", "t": "4.ある園芸店の新たな取り組み"}]}, {"head": "テレビでアナウンサーがコメンテーターに意見を聞いています。", "lines": [{"k": "spk", "s": "女", "t": "今回若者にターゲットに絞った新しいパソコンが発売されました。田中さん、今回お使いになってみたそうですが、いかがでしたか"}, {"k": "spk", "s": "男", "t": "悪くなかったですよ。色もカラフルで、この色の選択が自由にできるというのも、個性を大切にする今の若者にはびったりではないでしょうか。今の若い人は、機能性は言うまでもありませんが、デサイン性もかなり重視していますからね。でもね、分割で毎月少しずっ払う方法があると言っても、若者向けということであれば、価格はもっと抑える必要があったんじゃないでしょうかね購入者層の年齢をもう少し上に設定していたら、この価格で全く問題ないと思いますが男の人は、新しいパソコンは若者にとってどうたと言っていますか。"}, {"k": "ch", "t": "1.デザインもよく、値段も適当だ"}, {"k": "ch", "t": "2.デザインはよいが、値段は適当でない"}, {"k": "ch", "t": "3.デザインはあまりよくないが、値段は適当だ"}, {"k": "ch", "t": "4.デザインもあまりよくなく、値段も適当でない"}]}, {"head": "男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "卒業してから、もう3年か"}, {"k": "spk", "s": "女", "t": "そうだね。こうやって話すのも久しぶりだね"}, {"k": "spk", "s": "男", "t": "まだ同じ会社で頑張ってるんつだって、すぐ辞めるかと思ってたけど。"}, {"k": "spk", "s": "女", "t": "うん。もう少し大きい会社にと思って、いろいろ探してみたんだけどね局"}, {"k": "spk", "s": "男", "t": "働き出したころは、嫌になったら、自分で会社作っちゃおうって確かそんなこと言ってたよね。"}, {"k": "spk", "s": "女", "t": "そうだっけ?"}, {"k": "spk", "s": "男", "t": "でも、悪くないんでしょう、給料"}, {"k": "spk", "s": "女", "t": "どうかな。今の会社でどれだけ頑張っても、大手の7割ってところかな"}, {"k": "spk", "s": "男", "t": "じゃ、やつばりいつかは転職するつもり"}, {"k": "spk", "s": "女", "t": "うーん、'こにいても、自分が成長できない気がしたら、考えようと思ってたけど、私もまだまだ一人前ってわけじゃないから、まずはもっと勉強しなくちゃ。"}, {"k": "spk", "s": "男", "t": "へえ、君なら、給料が高かったら、業界変えてでも転職するんだと思ってた"}, {"k": "spk", "s": "女", "t": "いや、さすがにそれはきついよ。今はあまり率な行動はとらないようにしようと思ってる。"}, {"k": "spk", "s": "男", "t": "そっか。"}, {"k": "q", "t": "女の人は仕事について、今後どうしようと思っていますか。"}, {"k": "ch", "t": "1.自分で新しい会社を作る"}, {"k": "ch", "t": "2.給料の高い会社で働く"}, {"k": "ch", "t": "3.今の会社でしばらく働き続ける"}, {"k": "ch", "t": "4.新しい業界で働く"}]}, {"head": "ラジオで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "みなさん、動物の世界の時間です。動物の生活圏は水中、空、陸など様々ですが、そこでどのような生活を送っているのでしょうか。常に水の中を自由に泳ぎまわっているマグロ、空を飛び回っているアホウドリ。このような生き物は、人間のように活動を停止しなくても、水中や空を移動しながら眠ることができるんです。左右の脳を交互に休ませることによって、継続的な活動を可能にしているんですね。また、簟原に住むキリンなどの草食動物は、天敵から襲われないように、浅い眠りを保ち、完全に脳の活動を停止することはありません。一方、自分より強い天敵を持たないライオンは狩りをする以外の時間はのんびり寝て過ごしています。動物によってかなり違いますよね男の人は主に何について話していますか。"}, {"k": "ch", "t": "1.動物の生活圏"}, {"k": "ch", "t": "2.動物の脳の進化"}, {"k": "ch", "t": "3.動物の睡眠の取り方"}, {"k": "ch", "t": "4.動物と天敵の関係"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "text", "t": "近くの公園で先週あたりから、たくさんのひまわりが咲き出しました。そうしたら、通勤や買い物途中の人が足を止めてひまわりを見て、ひまわりきれいですねって話しているんです。花が咲いて、やっとひまわりに気がついた人が多いんですね。実はこのひまわり、町内会で子供たちも参加して種を撒いたんです。もうずいぶん前のことになりますけど。花は咲いてなくても、ひまわりは前からそこにあったんです。そして、皆が水をやったりして、すっと大切に世話をしてきた。これは、スポーツや勉強でも同じじゃないでしょうか。大輪の花を咲かせるという成果を得るためには、ずっと前に種を撒いて、長い間見えないところで努力をし続けなきゃならないんです。"}, {"k": "q", "t": "女の人が伝えたいことは何ですか。"}, {"k": "ch", "t": "1.結果を出すためには地道な努力が必要"}, {"k": "ch", "t": "2.公園の美化には地域ぐるみの協力が必要"}, {"k": "ch", "t": "3.植物を育てるには、日々の手入れが大切"}, {"k": "ch", "t": "4.スポーツや勉強も結果を出すことが大切"}]}, {"head": "会社で、女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "部長、お呼びでしょうか。"}, {"k": "spk", "s": "男", "t": "うん。新しい部署はどう?グループリーダーを任されるのは初めてだよね。"}, {"k": "spk", "s": "女", "t": "はい。プロジェクトの方向性を決定していく立場なので、とてもやりがいがあります。"}, {"k": "spk", "s": "男", "t": "そうか。君は入社当時からとにかく突っ走ってたからね。その頃から君のアイディアは斬新というか奇抜というか、注目されてたし。"}, {"k": "spk", "s": "女", "t": "お褒めに預かり、光栄です。"}, {"k": "spk", "s": "男", "t": "ただね、言うまでもないと思うけど、リーダーってのは自分の意見を通すことよりも部下の意見を吸い上げることに神経を使わなきゃいけないよね。"}, {"k": "spk", "s": "女", "t": "はあ。"}, {"k": "spk", "s": "男", "t": "もちろん、上司に言われるままに行動する部下にも問題があるわけだけど、上司が突っ走るタイプだと、意見を出しにくいとこもあると思うんだよね。"}, {"k": "spk", "s": "女", "t": "はあ、私はどんどん意見を出すように言ってるんですが"}, {"k": "spk", "s": "男", "t": "まあ、君みたいに積極的なタイプの社員ばかりじゃないからね。言葉で言うだけでなく、そういう雰囲気づくりも大事だよ。男の人は何のために女の人を呼びましたか。"}, {"k": "ch", "t": "1.新しい部署に移動させるため"}, {"k": "ch", "t": "2.斬新なアイディアを褒めるため"}, {"k": "ch", "t": "3.仕事の進め方について助言するため"}, {"k": "ch", "t": "4.プロジェクトについて意見を聞くため"}]}], "2013-12": [{"head": "会社の会議で男の人が話しています。", "lines": [{"k": "text", "t": "本社ビルの屋上で木や花を育てはじめて5年がたちました。都会の小さなオアシスとして、社員だけでなく、お客さまや迸隣の方にも喜ばれています。このたび、この屋上の一部をレンタル展園として隣住民の方々に貸し出すというアイディアが出て、話が進んでいます。っきましては、まずは社員で実験的に野菜を育ててみようと思っておりまして、今日からメンバーを募ります。農業の経験がある人も、興味はあるけどという初心者も歓迎です。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.ビルの屋上を利用する際の規則"}, {"k": "ch", "t": "2.レンタル農園の貸し出し方法"}, {"k": "ch", "t": "3.野菜を作る社員の募集"}, {"k": "ch", "t": "4.農業について學ぶ研修"}]}, {"head": "ホテルの経営会議で、女の人が経営の改善について話しています。", "lines": [{"k": "text", "t": "蓿泊客が減少し、業績が落ち込んでいる今、経営の改が必要です。そこで、提案したいのが、ホテル内にある直営レストランの見直しです。このレストランは、食時以外はほとんど客の利用がなく、維持費ばかりかかり、營の負担になっております。レストラン改装などダくさくによる客の増加に期待するよりも、飲食専門の会社と提携し、経費を抑えるほうが得策だと考えます。たとえば、1階のレストランをファミリーレストランに委託し、宿泊客には朝食クーポンを渡して、そこを利用してもらうというのはどうでしょうか。これなら、直営レストランがなくとも、サービスの低下にはなりませんし、委託先にとっても、ホテルの利用客が確実に自分の店の客になるので、双方にメリットがあるといえます。"}, {"k": "q", "t": "女の人は、何を提案していますか。"}, {"k": "ch", "t": "1.レストランの改装"}, {"k": "ch", "t": "2.置營レストランの設置"}, {"k": "ch", "t": "3.飲食専門の会社への業務委託"}, {"k": "ch", "t": "4.蓿泊客へのサービスの改善"}]}, {"head": "講演会で、男の人が話しています。", "lines": [{"k": "text", "t": "ええ、山川村で行われている山祭りは谷代に始まった伝的なお祭りですが、こ何年かは、つねに存続の危機が囁かれてきました。その主な原因として、指摘されてきたのは、資崟不足と人手不足です。資金のほうは、ここ数年で観晃業が贏道に乗ってきたことなどもあり、めどが立っているようですが、村の過疎化はいっこうに歯止めがかからす、祭りの次の担い手となる若者が不足しています。このような状況だと、5年後10年後の存続が難しいというのが現状です。"}, {"k": "q", "t": "男の人は主に何について話していますか。"}, {"k": "ch", "t": "1.篌的な祭りの歴史"}, {"k": "ch", "t": "2.祭りの存続にかかわる問題点"}, {"k": "ch", "t": "3.祭りを利用した観光客の誘薮"}, {"k": "ch", "t": "4.祭りを中止した理由"}]}, {"head": "テレビの経済番組で、レポーターが話しています。", "lines": [{"k": "text", "t": "今話題のこちらの店では、コーヒーや紅茶を飲みながら、本をじっくり選び、購入することができます。店内の客の大半は女性です。実はこちらでは、店内の本棚やテープルなどにも値札がついていて、インテリアを購入することもできます。まるで家具の販売店のようです。インターネットが普及し、小説や漫画もインターネットで購入できてしまう現在、町の書店は生き残りをかけ、様々な工夫を条なくされています。こちらでは、女性にターゲットを絞り、お茶を飲みながら本を選べるという新しい売り方を打ち出し、少しでも店に足を運んでほしいと努力をしているわけです。"}, {"k": "q", "t": "レポーターは何について話していますか。"}, {"k": "ch", "t": "1.女性向けの家具の売り方"}, {"k": "ch", "t": "2.女性が購入する本の傾向"}, {"k": "ch", "t": "3.インターネットて本を売るための工夫"}, {"k": "ch", "t": "4.ある書店の販売戦略"}]}, {"head": "ラジオで男の人が話しています。", "lines": [{"k": "text", "t": "希歩値の高い金属を希少金属といいますが、現在新たな鉱山開発に頼らずに、希少金属を確保する方法が模索されています。その中でも、特に注目されているのが、廃棄された携帯電話などから回収する方法です。実は、携帯電話などの電子機器には希少金属が多く含まれているのです。専門家の試算によると、日本国内にある電子機器などに使われている少金属の中には、世界の埋蔵量の1割を超えるものもあるそうです。電子機器からの再利用はコストが非常に高いのですが、天然資源には限りがあるわけで、積極的にこうした取り組みを進めていくべきだと思います。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.希少金属のリサイクル"}, {"k": "ch", "t": "2.希少金属の鉱山開発"}, {"k": "ch", "t": "3.世界の希少金属の埋"}, {"k": "ch", "t": "4.希少金属の廃彙処理"}]}], "2014-07": [{"head": "大学で女の学生と男の学生がある科目について話しています。", "lines": [{"k": "spk", "s": "女", "t": "先輩、去年「世界の言語」っていう科目とってましたよね。どうでしたか~"}, {"k": "spk", "s": "男", "t": "うーん。話しは専門的すぎて二年生には難しいし、先生は厳しいしさ。発表やら、レポートやら次々あって、あのときは、ちょっと後悔したね。"}, {"k": "spk", "s": "女", "t": "やつばりそうなんですか。そんなうわさ聞くんで、どうしようか迷っちゃって。"}, {"k": "spk", "s": "男", "t": "まあ、だけど、あそこであれやっといたからこそ、三年生の専門的な授業についてけてるんだと思うんだよね。"}, {"k": "spk", "s": "女", "t": "へえ、そうですか。"}, {"k": "spk", "s": "男", "t": "結局、先に苦しむか後に苦しむかだね。この科目先にとっとけば、後々楽になると思うよ。"}, {"k": "spk", "s": "女", "t": "ありがとうございました。考えてみます。"}, {"k": "q", "t": "男の学生はこの科目についてどう言っていますか。"}, {"k": "ch", "t": "1.難しいので、選択しないほうがよい"}, {"k": "ch", "t": "2.難しいが、後で役に立つ"}, {"k": "ch", "t": "3.易しいが、選択しないほうがよい"}, {"k": "ch", "t": "4.易しいし、後で役に立つ"}]}, {"head": "女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "ねえ、今話題の「山に生きて」って舞台、見た~"}, {"k": "spk", "s": "男", "t": "見た見た。昨日行ったんだけど、込んでたよ。"}, {"k": "spk", "s": "女", "t": "主演の林一郎すごかったよね。この前、「風に乗って」って作品にも出てたけど。あれと同じ人とは思えなかったわ。"}, {"k": "spk", "s": "男", "t": "そうだね。前回は粋で傷つきやすい青年って感じだったじゃない~ちょっとおどおどしてて。でも、今回は堂々としてて衣鬟のせいもあるのかな、体まで、大きく見えた"}, {"k": "spk", "s": "女", "t": "そうそう。歩き方からして違ってたもん。やつばりプロの俳優ってすごいよね。"}, {"k": "spk", "s": "男", "t": "そうだね。監督も絶してるみたいで、次の作品にもせひって言ってるんだって。"}, {"k": "spk", "s": "女", "t": "これからますます目が離せないね。"}, {"k": "q", "t": "ニ人は何について話していますか。"}, {"k": "ch", "t": "1.舞台のストーリ"}, {"k": "ch", "t": "2.谷表襄"}, {"k": "ch", "t": "3.俳優の性格"}, {"k": "ch", "t": "4.俳優の演技カ"}]}, {"head": "大学の食堂で女の学生と男の学生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "この間本で読んだんだけど、面白い研究があるんだよ。ペットの写真と飼い主の写真をバラバラに置いて、第三者に飼い主とペットの組み合わせを選んでもらうと、偶然とは思えない確率で当たるんだって、不思議だよね。"}, {"k": "spk", "s": "男", "t": "ああ、それ、僕も知ってる。ペットも長く一緒にいると、顔が似てくるっていう人がいるけど、僕、そうじゃないと思うんだよね。えっ~)うの~"}, {"k": "spk", "s": "男", "t": "その実験からはペットの顔が変わったのか飼い主の顔が変わったのかはわからないよね。"}, {"k": "spk", "s": "女", "t": "ああ、うん。"}, {"k": "spk", "s": "男", "t": "そもそも飼いはじめたときには似てなかったってことが証明されてないし、その時点で飼い主の選択が働いているわけだからさ。飼っているうちに似てきたってわけじゃなくて最初からってことなんだと思うんだよね。"}, {"k": "spk", "s": "女", "t": "おお、なるほどね。"}, {"k": "q", "t": "男の学生はペットと飼い主の外見について、どのように考えていますか。"}, {"k": "ch", "t": "1.ペットが飼い主に似てくる"}, {"k": "ch", "t": "2.飼い主がペットに似てくる"}, {"k": "ch", "t": "3.ペットと飼い主の外見には関連性がない"}, {"k": "ch", "t": "4.人は自分に似たペットを選んで飼う"}]}, {"head": "テレビのニュースでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "男", "t": "少子化が進み、一家族あたりの子供の数が減ると、家計に占める教育費の割合も下がると思われますが、そうとも言えないようです。教育研究所の調査結果によると、家計に占める教育費の割合はここ数年右肩上がりの状況が続いています。中でも、特に増加率が高いものは小さい子供、特に幼児にかける教育費です。これは小さい頃から子供に習い事をさせる家庭が増えていることが背景にあるようです。習い事の中でも特に人気なのは水泳、英語、音楽などて、月々払う月謝も増加傾向にあります。それに加えて、有名私立小学校を受験する子供の数が年々増えつづけていることも一因となっているようです。"}, {"k": "q", "t": "アナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.少子化による教育費の減少"}, {"k": "ch", "t": "2.家計に占める幼児の教育費の増加"}, {"k": "ch", "t": "3.人気のある幼児の習い事"}, {"k": "ch", "t": "4.有名私立小学校の人気の高さ"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "日本は四方を海に囲まれていることから、動物性たんばく質の摂取を魚に頼ってきました。ところが、食の欧米化とともに、最近は年々消費量が減ってきています。そこで、水カii土楽に前わる人々はもっと魚を食べてもらいたいという思いで、さまざまな提案をしています。その試みの一つが、ファストフードならぬファストフィッシュです。例えば、あらかじめ骨や皮が取り除いてあったり、野菜と一緒にレンジで加熱するだけで調理できるものが出てきましたこのような商品は今海外にも輸出されるようになりま男の人は主に何について話していますか。"}, {"k": "ch", "t": "1.日本と外国の魚の食べ方の比"}, {"k": "ch", "t": "2.魚の消費量が減った理由"}, {"k": "ch", "t": "3.魚の伝統的な調理方法"}, {"k": "ch", "t": "4.魚の消費量を増やす工夫"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "最近は郊外に進出している大型スーパーの影響で、昔からある商店街は買い物客が減り、経営が苦しいところが増えています。このような状況の中、緑町の商店街ではユニークな試みを始めました。今月から緑町商店街が緑マネーというこの町の商店でだけ使えるお金の制度を作りました。これは、例えば、お年寄りが子供たちに昔話を聞かせるとか、公園の清掃をするといったボランティア活動をするともらいます。町の人はボランティア活動で緑マネーをもらうことができ、「緑マネー」が使える商店街の店では、客を呼び込むことができます。今後、この「緑マネー」が普及し、お客が増えることを地元では期待しています。"}, {"k": "q", "t": "アナウンサーの話のテーマは何ですか。"}, {"k": "ch", "t": "1.大型スーパーの進出"}, {"k": "ch", "t": "2.子供のボランティア活動"}, {"k": "ch", "t": "3.商店街に客を呼ぶ取り組み"}, {"k": "ch", "t": "4.緑マネーの課題"}]}], "2014-12": [{"head": "ラジオで女の人が話しています。", "lines": [{"k": "text", "t": "水族館にはいろんな種類の魚や海の生物がいますが、イカは見たことありますか。見たことがないという人がほとんどじゃないでしょうか。水族館にいてもよさそうですが、実際はイカを朝育しているところは少ないんだそうです。イカは柿鬢なのて、小さい音にも反応して、を吐いて、水を黒くしてしまうというんです。それだと、鑑賞するには不向きですよね。もともと寿命も短く、一年ぐらいしか生きないそうです。水族館が敬遠するのも分かりますね。"}, {"k": "q", "t": "女の人は何について話していますか。"}, {"k": "ch", "t": "1.イカを飼育する水族館が少ない理由"}, {"k": "ch", "t": "2.イカを鑑賞する時の注意点"}, {"k": "ch", "t": "3.イカを水族館で飼うという取り組み"}, {"k": "ch", "t": "4.水族館のイカが長生きしない原因"}]}, {"head": "大学の留学生向けの就職説明会で男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "就職課の佐藤です。就職課では皆さんのように、日本での就職を考えている留学生の支援に力を入れています。ええ、このところ特に留学生の採用を考えている企業が増えていますが、日本で就職しようと考えているなら企業側がどんなことを求めているのかを知っておく必要があります。語学ができる人材がほしいのは当然ですが、もっとも期待されているのは日本人だけの集団では出てこないような発想ができることです。生まれ育った国で培われた感性、それから日本での留学中異文化の中で養われた感覚へ、そういったものを活かして活躍してほしいということなんです。"}, {"k": "q", "t": "男の人が何について話していますか。"}, {"k": "ch", "t": "1.大学の就職支援の内容"}, {"k": "ch", "t": "2.就職のための語学学習の必要性"}, {"k": "ch", "t": "3.日本企業が留学生に望むこと"}, {"k": "ch", "t": "4.留学生が就職しやすい企業"}]}, {"head": "テレビで男の人が在宅勤務について話しています。", "lines": [{"k": "text", "t": "最近、在宅勤務つまり出動せずに自宅で働くシステムを導入する企業が少しずっ増えています。在宅勤務の制度を導入することで、人材を有効に活用できるというメリットがあります。ただ在宅勤務の人に対しても勤務時間の管理や健康管理を、通常の勤務の人と同じように行う必要があります。つまり、導入に当たっては、労働者が決まった労働時間を守って働いているか、職場から孤立した環境で精神的にストレスを感じていないかなどを、雇用者側が管理していくことが求められます。"}, {"k": "q", "t": "在宅勤務についてどんなことを話していますか。"}, {"k": "ch", "t": "1.導入した会社の事例"}, {"k": "ch", "t": "2.会社が留意すべきこと"}, {"k": "ch", "t": "3.働く人のメリット"}, {"k": "ch", "t": "4.働く人のストレスの解消方法"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "text", "t": "ん一今日は井上次郎の小説ー「夏の日」を取り上げます。この小説は、今から七十年以上前に書かれた作品ですが、発表された当時の社会的な出来事や世の中の様子、さらに風などを理解した上で読むと大変楽しめます。たとえば同時の社会では、女性がスーツを着ることはほとんどありませんでした。この小説の中である女性がスーツを着ていると書かれている箇所がありますが、この表現からはかなりのえー私はこの地域で分かるんです。知らなければ見過ごしてしまう描写ですが、これを知っていれば、理解がずいぶん変わるはずです。今日はこういった基礎知識を講義したいと思います。"}, {"k": "q", "t": "今日の授業でこのあと主に何について勉強しますか。"}, {"k": "ch", "t": "1.この小説に描かれている時代の背景"}, {"k": "ch", "t": "2.この小説の歴史的な意義"}, {"k": "ch", "t": "3.働く女性の服装の歴史"}, {"k": "ch", "t": "4.小説を書くための基礎知識"}]}, {"head": "講演会で農家の男の人が話しています。", "lines": [{"k": "text", "t": "ん一私はこの地域で長年農業の活性化に取り組んできましたが、農家の高齢化が進んで農業の担い手は減る一方なんです。家が農家で土地があったとしても、体力と根気が必要な大変な仕事ですから、後継者になろうとはなかなか思ってくれないんです。人々の暮らしを支える農業という仕事はやりがいがあって魅力的だとよく言われますが、やりがいだけでは...まあ、なんといっても、自分と家族の生活もありますからね。それなりに収入がなければ続きません。ただ実際は農作物の収穫が天候に左右される不安定な側面もあって、十分な収入を得るのはなかなか難しいんです。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.農業の活性化のための取り組み"}, {"k": "ch", "t": "2.農業の後継者が減少している理由"}, {"k": "ch", "t": "3.農家における暮らしの変化"}, {"k": "ch", "t": "4.農家の収入を増やす方法"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "text", "t": "秋になると、木の葉が赤や黄色に染まりますね。これは植物の葉が枯れて落ちる前に起こる現象で、老化現象の一種なんです。気温が低くなる秋には植物の活動が鈍くなります。この時葉の付け面に特殊な細胞の層ができて、その部分から葉が落ちやすくなるんです。気温が低くなるまでには、葉で作られた糖分は木全体に行き渡るようになっているんですが、この細胞の層ができると、それができなくなって、糖分が葉にたまっていくんです。そして、そのたまった糖分が色素に変わるわけです。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.植物の健康状態を知る方法"}, {"k": "ch", "t": "2.植物が枯れないようにする方法"}, {"k": "ch", "t": "3.木の葉が栄養を作り出す仕組み"}, {"k": "ch", "t": "4.木の葉が色づく仕組み"}]}], "2015-07": [{"head": "ラジオで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "猫が喉をごろごろと鳴らしながら気持ちよさそうに寝ている姿はかわいらしくて、見ているだけで癒されます。これは、母猫が子猫を安心させるためによく出す音なんですが、他にも気分がいい時や、リラックスしているときも鳴らしています。でも実は、体調が悪いときにもこの音を出していると言われているんですよ。猫は骨折しても他の動物と比べて、倍以上の速さで回復するそうですが、その秘密ももしかしたら、この音を出すことと関係があるのかもしれないという話を聞いたことがあります。私はこのごろごろには他にも何か特別な力があるのではないかと思っているんです。"}, {"k": "q", "t": "問い男の人は何について話していますか。"}, {"k": "text", "t": "1猫が人にもたらす癒し。2猫の愛情表現の方法。3猫が出す喉の音。4猫の回復の速さ。"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "text", "t": "このクリップトメールは朝立以来わが社でずっと販売してきた商品ですが、ある年を境に吉れ上げが一気に跳ね上がったんです。テサインの改良や、価格の見直しもなかったときのことでしたのて、一体どうしたのか見当もつかなかったのですが、消費者アンケートの結果からあることが分かりました。受験を控えたお子さんを持っ親が、受験を前に食卓に勝てそうな名前の食べ物、例えば、豚カツなどを並べるというようなことをしますが、私どもの「トメール」もその親子さんの気持ちにお応えできたようです。「落ちる」のを「とめ~る」、なるほどなと、せめてもの親心がクチコミとなってネット上で広がったわけなんですね。"}, {"k": "q", "t": "問い男は何について話していますか。"}, {"k": "text", "t": "1商品が急に売れ出した理由。2商品開発の裏話。3商品デザインを改良したきっかけ。4開発者が商品に込めた気持ち。"}]}, {"head": "テレビで、サッカー選手が話しています。", "lines": [{"k": "text", "t": "「えー、私はこの度、現役生活に終止符を打っことにいたしました。昨年、試合中に負傷してしまい、大きな手術を受けました。必死のリハビリが実って、今シーズン終盤には何とか試合に出場することができ、最後は、チーム態願の優勝を果たすことができました。チームとしては最高の結果を得て、この上ない感動を味わいましたが、個人的に満足のいくプレーができたといえば、そうではありません。自身が得のいくプレーができなくなった以上、今後継続していくことは難しいと感じました。怪我をして辛かったときに、支えてくれたファンやスタッフの方々、チームメート、そして家族には、感謝の気持ちでいつばいです。」"}, {"k": "q", "t": "問いサッカー選手は主に、何について話していますか。"}, {"k": "text", "t": "1怪我が治って、復帰できた喜び。2優勝したときの感動。3引退を決意した経緯。4選手を支える人々の大切さ。"}]}, {"head": "大学で、女の学生と男の学生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "このまえ、大学院に行くか、就職するか迷ってるって言ってたけど、進路、どうするか決めた~"}, {"k": "spk", "s": "男", "t": "それがさあ、先輩に「大学院に行こうかと思ってるんですけど」って相談したら、「就職するのが嫌なだけじゃないのか」って言われてさあ、最初はそんなことあるもんかってちょっとむっとしたんだけど、いろいろ話してたら、先輩に言われたこと、案外当たってるかもって思えてきて。"}, {"k": "spk", "s": "女", "t": "そうなんた"}, {"k": "spk", "s": "男", "t": "うん。周りが就職活動をし始めたから、焦ってきちゃって、でも、流されないぞって思って、自分なりにしつかり考えたつもりだったんだけど、結局嫌なことを先延ばしにしてただけかなって。"}, {"k": "spk", "s": "女", "t": "うーん。"}, {"k": "spk", "s": "男", "t": "今大学院に行く必要があるのかとか、行くにしても、なにを研究したいのかっていうのは、二の次になってたし、将来どんな仕事がしたいのかってのも、ちゃんと考えてたわけではじゃないことに気がついたんた"}, {"k": "spk", "s": "女", "t": "そっか、じゃあ、振り出しに戻っちゃったね"}, {"k": "spk", "s": "男", "t": "そうでもないよ。今自分が何を考えなきやいけないかがはっきりしたから、大いなる進歩さ。"}, {"k": "spk", "s": "女", "t": "うーん。"}, {"k": "q", "t": "問い男の学生はいま進路についてどう思っていますか。"}, {"k": "text", "t": "1大学院に行きたいが就職する。2就職したいが大学院に行く。3就職した後で大学院に行く。4進学か就職かもっとよく考えたい。"}]}, {"head": "テレビで専門家が話しています。", "lines": [{"k": "spk", "s": "女", "t": "現在、若い世代では共働きの家庭も多く、出産後働きつづける女性が増え、労働と育児の両立という問題に直面している人が少なくありません。また、今後高齢化が進むと、働きながら家族の介護をする人が増えることも懸念されます。こういった問題は長時間労働が常態化している企業があることや有給休暇を積極的に取得しない人がいるという現状をなんとかしなければ、解決は難しいと考えます。最近では、企業が出産、育児、介護など、各種休業制度を設けていますが、制度を導入するだけでは、十分とはいえません。企業や労働者が置かれいてるこうした現状をしつかりと見直す時期に来ているのではないでしょうか。"}, {"k": "q", "t": "問い専門家が言いたいことはなんですか。"}, {"k": "text", "t": "1女性の社会進出を支援すべきだ2若い世代も介護の重要性を認識すべきだ。3介護や保育を担う人材を育成すべきだ4現在の労働のあり方を改善すべきだ。"}]}, {"head": "経済研究所のセミナーでデータ分析の専門家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "えー、企業は自社における仕入れや売り上げる記録など様々なデータを蓄積してますが、データは数値そのままでは何ら意味を持ちません。私たちの仕事はそれぞれの数値の関連性を分析し、企業にとって有益となる新たな可能性を示すことです。データの分結果を提示する際は、普段データを目にすることがない人でもよく理解でき、活用できるよう、見せ方を工夫する必要があります。例えば、客が一度の買い物で購入する商品の関連性が分かるように、図で示すことがありますが、線の濃淡やグラフの種類など、視覚的にわかりやすくするだけでも、入荷量なり、陳列方法なりの改善点に気づくことができるんですよ。データから数値以外のものまで読み取ることができるよう加工を施す。それが我々の使命と考えています。"}, {"k": "q", "t": "問い専門家が主に何ついて話していますか。"}, {"k": "text", "t": "1分析結果の提示方法の重要性2分析結果の解釈の多様性3企業に蓄積されたデータの種類4データを加工することの難しさ"}]}], "2015-12": [{"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "最近、家やオフィスに防災用へルメットを置くところが増えていますが、保管場所に困っている人も多いのではないでしょうか。そんな中、人気を集めている商品があります。ある防災用品メーカーが開発した折りたたみ式のヘルメットです。独自に開発した樹脂素材が使われていて、強度はそのままで、折り畳みが可能となっています。軽くて組み立てるのも簡単です。昨年は八万個以上も売れたそうです。"}, {"k": "q", "t": "女の人は何について話していますか。"}, {"k": "ch", "t": "1.防災用品の適切な保管場所"}, {"k": "ch", "t": "2.新しい防災用品の開発の苦労"}, {"k": "ch", "t": "3.新しいへルメットの販売方法"}, {"k": "ch", "t": "4.ある防災用へルメットの特徴"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "男", "t": "この十年、海外に留学する日本人学生が減少しています。若者が海外との交流に消極的になっているからだという声も聞かれます。しかし、これには、学費の値上げをする留学先が増えたことや、就職活動を開始する時期に間に合わず、留学が就職活動において不利になる場合もあることも影響しています。また、採用の際、海外経験の有無を重視しない企業が少なくないことなどもあるようです。となれば、一概に若者が消極的になったせいたとも言えません。こうした実情もあるのです。"}, {"k": "q", "t": "アナウンサーは、何について話していますか。"}, {"k": "ch", "t": "1.留学する日本人学生が減っている原因"}, {"k": "ch", "t": "2.日本への留学生を増やす計画"}, {"k": "ch", "t": "3.若者に留学に興味を持たせる方法"}, {"k": "ch", "t": "4.海外で就職することの難しさ"}]}, {"head": "ラジオでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "男", "t": "夏は海や山といった行楽地にお出かけになる機会も多いと思いますが、雷に注意することが必要な季節です。ごろごろといった音が聞こえたら、いかに小さい音であれ、まだ大丈夫だと過信せず、すぐに避難する必要があります。え、雷は高いビルや木などに落ちる性質があるので、木などへは近寄らず、すぐに屋内に入るようにします。もし、海や山などにいて、適切な避難場所がない場合には、高い木などのそばから離れて低い姿勢を取ることが大切です。"}, {"k": "q", "t": "アナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.雷が発生しやすい地域"}, {"k": "ch", "t": "2.雷による被害"}, {"k": "ch", "t": "3.雷が発生する仕組み"}, {"k": "ch", "t": "4.雷が発生した場合の対処法"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "皆さんは、人と会話をしているときに、思わず相手と同時に話をし始めてしまった経験はありませんか。そんなとき、皆さんはすぐに話を止めて、「どうぞ」と譲り合うのではないでしょうか。しかし、どの社会にでもいえることてしようか。とある少数民族はこのようなとき、話を止めず、お互いに延々としゃべり続けるといいます。それでは、会話は成り立っていないと考える人も多くいるでしょう。しかし、その少数民族の社会においては、互いに同時に話し続けることが当たり前の日常なのです。"}, {"k": "q", "t": "先生が伝えたいことは何ですか。"}, {"k": "ch", "t": "1.会話のトラブルは避けたほうがいい"}, {"k": "ch", "t": "2.ある少数民族の会話の仕方はすばらしい"}, {"k": "ch", "t": "3.会話の仕方は社会によって異なるものだ"}, {"k": "ch", "t": "4.会話では相手の話を聞くべきだ"}]}, {"head": "テレビのニュース番組でアナウンサーが話しています。", "lines": [{"k": "spk", "s": "男", "t": "桜町といえば、山の斜面に畑が広がるのどかな風景が有名です。しかし農家は後継者不足で高齢化が進み、この傾斜地での作業は負担が大きいため、雑草が伸びたまま、手入れされない畑も多く見られました。そこで桜町では、近くの無人島のヤキを連れてきて畑に放牧し、雑草を除去することにしました。このヤギは、島に人がいなくなった後、野生化して、島の貴重な植物を食べ、生態系を破壊する恐れがあったため、いい機会だったというわけです。桜町では、野生のいのししによる農作物の被害も増えていましたが、草むらがなくなったことで、警戒心の強いいのししは身を隠す場所を失って、寄り付かなくなったそうです。"}, {"k": "q", "t": "何についてのニュースですか。"}, {"k": "ch", "t": "1.農家の後継者不足を解消する方法"}, {"k": "ch", "t": "2.農家の作業にヤギを活用している例"}, {"k": "ch", "t": "3.家畜による農作物被害の増加"}, {"k": "ch", "t": "4.いのししによる生態系の破壊"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "日本では、雪が多いいくっかの地域で、春先のよく晴れた日に、長く愛用した着物の生地を雪の上にさらすということが百年ほど前まで行われていました。太陽の熱で溶け出した雪が水蒸気になり、それが太陽の日差しに当ることにより化学反応が起こって、汗の染みなどが消え、染められた布の色が蘇るんだそうです。昔、洗剤などがまだない頃、着物を綺麗にするすべがないかと工夫を重ねた人々が、自然環境を活かして生み出したものです。着物を着ることが少なくなった現在でも、部の人によって行われているそうです。着物を着るという習慣の中で培われてきた知恵を感じることができます。"}, {"k": "q", "t": "女の人は何について話していますか。"}, {"k": "ch", "t": "1.着物の染みを取る伝統的な方法"}, {"k": "ch", "t": "2.雪の日に着物が汚れないための工夫"}, {"k": "ch", "t": "3.伝統的な着物の柄の美しさ"}, {"k": "ch", "t": "4.着物を綺麗に保存することの難しさ"}]}], "2016-07": [{"head": "女の学生と男の学生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "ねえ、中山くん、大学の近くの一軒家に住んでるんだってね。実家じゃなかったよね。"}, {"k": "spk", "s": "男", "t": "うん。石田さんという人のところなんだけどね。「異世代ホームシェア」っていって、一人暮らしのおりが学生向けに部屋を安く提復してくれてるんだ。いわゆる「下宿」"}, {"k": "spk", "s": "女", "t": "へえーお年りのところに下宿ってどんな感じ~"}, {"k": "spk", "s": "男", "t": "うん、生活リズムが違うし、お風呂に入る時間が遅いとか、電気はこまめに消してほしいとか、いろいろうるさく注意されることもあるけど。"}, {"k": "spk", "s": "男", "t": "でも石田さん多趣味で博学だから、いろんなこと知ってて、話聞いてると気がついたら深夜になってるってこともあるんだ。退屈しないよ"}, {"k": "spk", "s": "女", "t": "ふん一、私だったら他人と生活するのは気をつかっちゃうなあ。"}, {"k": "spk", "s": "男", "t": "まあ、それなりにね。でも、石田さんにしても、他人のぼくが入ってきたわけだし、お互い様だから。"}, {"k": "spk", "s": "女", "t": "そっか。"}, {"k": "q", "t": "男の学生は、今住んでいる家での生活について、どう思っていますか。"}, {"k": "ch", "t": "1.気をつかってばかりで居心地がよくない"}, {"k": "ch", "t": "2.気をつかうこともあるが悪くはない"}, {"k": "ch", "t": "3.気をつかうこともなく満足している"}, {"k": "ch", "t": "4.気をつかうことはないが退屈た"}]}, {"head": "テレビでスポーッコメンテーターが話しています。", "lines": [{"k": "spk", "s": "男", "t": "プロのスポーツ選手は日頃からバランスのよい食事を意識し、なみなみならぬ努力とトレニングを重ねることで、強くしなやかな肉体を手に入れていますが、中でもトップクラスの選手は肉体に加え、「ここぞ」という緊迫した場面で平静を保っことができる強さをもっています。観客がかたずをのんで見守るような場面でも動じることなく本来の力が発揮できる内面の強さ、試合でよい結果を出すにはこの点に特化したトレーニングが不可欠です。これは試合の結果を大きく左右する要素だといえるでしょう。"}, {"k": "q", "t": "スポーッコメンテーターは主に何について話していますか。"}, {"k": "ch", "t": "1.日々の食事内容が試合に与える影響"}, {"k": "ch", "t": "2.強くしなやかな体の作り方"}, {"k": "ch", "t": "3.精神力を養うことの重要性"}, {"k": "ch", "t": "4.緊を解くためのトレーニング方法"}]}, {"head": "会社で社長が話しています。", "lines": [{"k": "text", "t": "わが社は加工食品メーカーとして、開業以来、お客様に喜んでいただける商品作りに取り組んでいますが、さらに広く多くの方に'わが社の味を知っていただくため、海外に進出する朝を長年持ち続けてきました一時期業績が振るわず実現が危ぶまれたこともありましたが、ようやく来年度、海外工場建設カ二に着手できる見込みとなりました。現地での人員の確保や教育、販路の新規開拓など課題は山積していますが、現地工場でも品質を損なうことのないよう、これまでどおり質の高い商品を生産し、販売していきたいと思います。"}, {"k": "q", "t": "社長は主に何について話していますか。"}, {"k": "ch", "t": "1.新たに展開する海外事業"}, {"k": "ch", "t": "2.質の高い商品の開発"}, {"k": "ch", "t": "3.来年度発売する新商品"}, {"k": "ch", "t": "4.来年度の業績見込み"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "みなさんは、日々の生活の中で頑張っていることはありますか。勉強や仕事、あるいは貯金などさまざまだと思います。何事も高い目標を掲げ、諦めることなく、それに向かって努力すれば、それだけ自分にかえってくるものも大きいのは確かです。反面、過厖に行うと、視野が狭くなったり、バランスを崩すこともあります。たとえば、貯金するために日々頑張ってをしているという方がいらっしやるかもしれませんが、行き過ぎると、周りからけちで付き合いにくい人だと思われてしまうこともあります。このような点を考慮しつつ、目に向かって頑張ることで、よりよい生活が送れるのだと思います。"}, {"k": "q", "t": "女の人が言いたいことは何ですか。"}, {"k": "ch", "t": "1.何をやるにも全力で取り組むべきだ"}, {"k": "ch", "t": "2.何をやるにも目標を高めにしたほうがいい"}, {"k": "ch", "t": "3.何をやるにも行き過ぎないことが大切だ"}, {"k": "ch", "t": "4.何をやるにも諦めが心た"}]}, {"head": "テレビでコメンテーターが国立公園について話しています。", "lines": [{"k": "spk", "s": "女", "t": "国立公園に指定されている桜高原が今、鳬機に直面しています。これまて、当然保護の観点から、地元の西山市によって、立ち入り人数や時間の規制がなされてきましたが、その制約の厳しさから、訪れる人が減し、それによって、地元の人々の関心までもがれてきているのです。桜高原では、これまで地元の非営利団体がボランティアを募って、清掃活動を行うなど、積極的に保護活動に取り組んできましたが、こ数年は、人が集まらず、以前のような活動ができなくなっているそうです。保護か公開か、一者択一ではなく、何のための公開か、その目的を再確認し、管理、運營のあり方を見すことが気務てはないでしょうか。自治体の対応が期待されます。"}, {"k": "q", "t": "コメンテーターが言いたいことは何ですか。"}, {"k": "ch", "t": "1.訪れる人を増やすために宣伝をするべきた"}, {"k": "ch", "t": "2.現在の規制内畧を再考するべきだ"}, {"k": "ch", "t": "3.当然保護の規制を厳格にするべきだ"}, {"k": "ch", "t": "4.自然保護活動は自治体に任せるべきだ"}]}, {"head": "テレビで労働問題の専門家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "働く人にとって、労働時間と日常生活のバランスを保っことは大切で、これを健康羅持にも不可欠ですが、現実はなかなか思うようにいかないようです。そこで、政府は有給休暇の取得を進する方針を打ち出しました。有給の取得率は恒常的に低く推移していて、こを何とかすることが、現状の改善に向けた大きな一歩だと考えているからです。とはいえ、長年続いてきた働き方の習慣を変えるのは容易なことではありません。政府は、事業者に対して、一斉休業日を設けることや、従業員に一年間の採取得計画を提出させることを奨励しています専門家は主に何について話していますか。"}, {"k": "ch", "t": "1.労働時間と健康の関係"}, {"k": "ch", "t": "2.働く人の健康意識を高める方法"}, {"k": "text", "t": "しゅ冫くりつへんかしゅダくりつ"}, {"k": "ch", "t": "3.有給休暇の取得率の変化"}, {"k": "ch", "t": "4.有給休暇の取得率をあげる政府の取り組み"}]}], "2016-12": [{"head": "衣服の専門学校の授業で先生が話しています。", "lines": [{"k": "text", "t": "皆さんは服装を決める時、天気や出かける場所だけではなく、気分で服装を選ぶこともあると思います。また、反対に身につけた服装や小物により、一日を気分よく過ごせることもあるでしょう。実際に高齢者が装いに変化を付けファッションに気を配ることで、気持ちが前向きになったという研究結果があります。また、怪我が原因で入院し、リハビリ治療が必要な患者が療の一環として普段とは異なる華やかな服装にしたところ、心に張りが生まれ、リハビリ意欲がしたという報告もあります。このようなことがいま注目されています。"}, {"k": "q", "t": "先生の話のテーマはなんですか?"}, {"k": "ch", "t": "1.服装を選ぶ際の判断基準"}, {"k": "ch", "t": "2.おしゃれをすることが心理状態にもたらす効果"}, {"k": "ch", "t": "3.高齢者のおしゃれに対する関心の高さ"}, {"k": "ch", "t": "4.リハビリを行いやすい服装"}]}, {"head": "テレビで女の人が話しています。", "lines": [{"k": "text", "t": "最近は珍しい外来種の動物や虫などを飼う人も多いようです。外来種とはもともと生きていた地域から異なる地域へ、人の移動に伴って運ばれてきた生き物のことを言います。このような外来種のペットを最後まで世話をしきれずに、安易に捨てる人が増えています。それらが野生化して殖した結果、白笨箇有の生き物とえさばや住む場所を巡って争ったり、それまでになかった病気が広がり、生態系に深刻な影響をもたらしたりしているんです生き惕は責住を持って飼い、日本固有の生き物や日本の生態系を守っていきたいものです。"}, {"k": "q", "t": "女の人は何について話していますか。"}, {"k": "ch", "t": "1.外来種を飼う人が増えている理由"}, {"k": "ch", "t": "2.外来種が繁殖しやすい地域"}, {"k": "ch", "t": "3.外来種がもたらした病気の種類"}, {"k": "ch", "t": "4.外来種のペットが野生化したことによる問題"}]}, {"head": "テレビで博物館の人が話しています。", "lines": [{"k": "text", "t": "歴史博物館の館内改装に際し、力を注いだのは当館のメインとなっている百年前の町並みを紹介するフロアです。当時の街並みを精巧に再現した模型は改襄以前から展示しておりましたが、この模型にスポットライトを用いて、通りや建物、人物などを際立たせるという演出を試みました。更に、本物らしさを追求して、色や明るさ、照らす角度に変化を持たせることにより、昼夜の変化を描いております。当時の人々の暮らしぶりに思いを馳せていただけるようにできたかと思っています博物館の人は何について話していますか。"}, {"k": "ch", "t": "1.百年前の建物の特徴"}, {"k": "ch", "t": "2.模型を精巧に作る難しさ"}, {"k": "ch", "t": "3.展示物にあてる照明の工夫"}, {"k": "ch", "t": "4.昔の人々の暮らしを展示する目的"}]}, {"head": "テレビでレポーターが話しています。", "lines": [{"k": "text", "t": "こアサヒ町は葡朝の産地として知られています。おいしい葡朝と豊かな自然を求めて、観晃客が数多く訪れています。また、この地は音楽家を多数輩出したことでも知られています。音楽に関係の深いこの町ですが、最近は葡萄の木にこの土地で作られた曲を聞かせているそうなんです。そもそも農作業の合間に曲を聴いていた農家の人たちが、ふっと成長が早まりはしないかと思いっき、以後続けているそうです。この方策の効果については、適度な振動が枝の成長を進する可能性があるとのことです。心地よい音色は展筰業の疲れも癒してくれそうですね。"}, {"k": "q", "t": "レポーターは何について伝えていますか。"}, {"k": "ch", "t": "1.葡萄の栽培に必要な条件"}, {"k": "ch", "t": "2.観光客を増やすための方策"}, {"k": "ch", "t": "3.音楽を用いた葡萄の栽培の試み"}, {"k": "ch", "t": "4.作業の疲れを癒すのに適した音楽"}]}, {"head": "ラジオで医者が話しています。", "lines": [{"k": "text", "t": "年を重ねるにつれて、体の様々な所に老化の症状が現れます。目も例外ではありません。レンズの役割をしている部分の弾力性が低下すると、この部分の厚みを変えることが難しくなり、目のヒントを調節する機能が徐々に衰えます。近くの物がぼやけて見えるようになり無理ちょーせつきのうゑして見ようとすることで、目が疲れやすくなります。目の調機能の表えを止める方法はありませんが、目の筋肉をえ、血液の流れをよくすることで目の疲れの症状を緩和することがてきます。また、目に負担をかけないためにも、必要に応じてメガネを掛けるなどするとよいでしょう医者は何について話していますか。"}, {"k": "ch", "t": "1.目の老化現象とその対処のしかた"}, {"k": "ch", "t": "2.目が疲れた時の症状"}, {"k": "ch", "t": "3.目の健康状態をチェックする方法"}, {"k": "ch", "t": "4.症状にあったメガネの選び方"}]}, {"head": "講演会で男の人が話しています。", "lines": [{"k": "text", "t": "私は私は長年鮭の生態を調査・研究してきました。鮭は川で生まれ、遠く離れた海で育ち、また生まれた川に帰って産卵し、その一生を終えます。川にはその川ごとの特有の匂いがあります。これまでの調査から鮭は川に帰る際、一つは川の匂いを頼りとしていることがあきらかになっています。しかし、鮭は何千キロも離れた海まで移動するため、川の匂いだけを頼りにしているとは考えにくいのです。まだ明らかにされていないこともありますが、太陽の位置をもとに、現荏の位置を把握するなど、いくつかのことを併用していると考えられています。"}, {"k": "q", "t": "男の人は主に何について話していますか。"}, {"k": "ch", "t": "1.鮭が川から海へ移動する理由"}, {"k": "ch", "t": "2.鮭が生まれた所に戻る方法"}, {"k": "ch", "t": "3.鮭が好む川の匂いの特徴"}, {"k": "ch", "t": "4.鮭が育っ川の環境を保護する必要性"}]}], "2017-07": [{"head": "大学で、女の学生と男の学生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "テレビで見たんだけどね、変わった病院があるみたいだよ。美術館みたいに、廊下にも病室にも絵がかけてあって、病室の壁も白じゃなくて、オレンジやピンクなんだって"}, {"k": "spk", "s": "男", "t": "へえ、そんな病院があるんだ"}, {"k": "spk", "s": "女", "t": "うん。職員からは、そんなことに使うお金があったら、医療機器をもっと充実させてほしいって声もあるらしいけど、患者さんからの評判はいいみたいで。確かに、映像を見てると、表情がいきいきしてるなあって思った"}, {"k": "spk", "s": "男", "t": ""}, {"k": "spk", "s": "女", "t": "ほかにもね、院内で、患者も参加して、演奏会やファッションショーを開いたり、医療行為以外の形で、患者さんたちが元気になるようないろんな活動をしてるらしいよ。"}, {"k": "spk", "s": "男", "t": "えつ。患者も出るわけ~僕だったら、それがストレスになりそう。"}, {"k": "spk", "s": "女", "t": "はじめは尻こみしてた人も心待ちにするようになるんだって。"}, {"k": "q", "t": "女の学生はこの病院の取り組みについて、どのように言っていますか。"}, {"k": "ch", "t": "1.患者の気持ちが明るくなってよい"}, {"k": "ch", "t": "2.医療機器の充実につながってよい"}, {"k": "ch", "t": "3.患者参加型の治療は逆効果だ"}, {"k": "ch", "t": "4.治療としての効果は期待できない"}]}, {"head": "ラジオで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "よく行くすし屋の主人が言ってたんですけど、あっ、この店は仕事帰りのサラリーマンでいつもにぎわってるんですけどね。お店に来る最近の若い人たちは仕事以外で上司と付き合いたくないっていう人が多いらしいんですよ。まあ、仕事の後で食事などに一緒に行きたくないってことですよね。あと、年賀状のやり取りなんかも、極力したくないらしいですよ。プライベートな話をすることもないようで、私もその店で、上司と部下らしき人が一緒に来ているのを見たことがありますけど、あの人たちも、言葉は悪いですけど、上司としぶしぶ付き合ってるってことなんですかね。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.サラリーマンに人気のお店"}, {"k": "ch", "t": "2.退社後のサラリーマンの時間の使い方"}, {"k": "ch", "t": "3.職場におけるコミュニケーションの大切さ"}, {"k": "ch", "t": "4.今の若者の上司との付き合い方"}]}, {"head": "テレビで専門家が話しています。", "lines": [{"k": "spk", "s": "女", "t": "日本には、農村地域などに屋敷林といって、家の周りに植えられた人工的な林があります。強い季節風から家屋を守ったり、枝や幹を木材として、生活の中で使ったりという機能かありました。しかし、人々の暮らしが近代化するのに伴い、その必要性は徐々に薄れ、町の開発などによって、減少してきました。各地に残っている屋敷林は、現代では、緑の豊かさやその地域の代表的な景観として価値のあるものとなっています。"}, {"k": "q", "t": "専門家は何について話していますか。"}, {"k": "ch", "t": "1.屋敷林の役割の変化"}, {"k": "ch", "t": "2.屋敷林を保存する活動"}, {"k": "ch", "t": "3.地域による屋敷林の特徴"}, {"k": "ch", "t": "4.屋敷林の跡地の利用法"}]}, {"head": "会社の会議で、女の人と部長が話しています。", "lines": [{"k": "spk", "s": "女", "t": "今度出す清涼飲料水の宣伝用ポスターの案は今お話ししたとおりなんですが、部長いかがでしょうか。"}, {"k": "spk", "s": "男", "t": "このポスターの言葉、広告としてはおもしろいし、若者の心もつかむだろうけどね。確かに、今回の新商品は若者を意識して、ラベルも開発してきたんだけど、ポスターをここまで若者寄りにしていいんだろうか。"}, {"k": "spk", "s": "女", "t": "はあ。"}, {"k": "spk", "s": "男", "t": "売り上げを考えると、若者に寄りすぎず、広告はもう少し幅広い層を意識した表現のほうがいいんじゃないかな。そうしないと、売り上げ目標の達成は難しいと思うんた"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "商品のラベルとも印象が違いすぎるしね。もしこの表現にするなら、商品のラベルなんかも、もっと若者向けにかえていくぐらいじゃないとだめだと思うけど。今からそれが可能かというとね"}, {"k": "spk", "s": "女", "t": "確かに、そうですね。"}, {"k": "q", "t": "部長はどのような意見ですか。"}, {"k": "ch", "t": "1.ポスターと商品のラベルを変更する"}, {"k": "ch", "t": "2.ポスターも商品のラベルも変更しない"}, {"k": "ch", "t": "3.ポスターは変更するが、商品のラベルは変更しない"}, {"k": "ch", "t": "4.ポスターは変更しないが、商品のラベルは変更する"}]}, {"head": "ラジオでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "ペットを飼う一人暮らしの高齢者が増えており、家族のように頼りにしている人も多いようです。一方で、飼い主が急に入院などをしなければならなくなった場合、預け先などに困るというようなケースも増えています。このような事情を背景に、現在様々な取り組みが始まっています。ある地域では、ボランティアが散歩や餌やりを代行したり、獣医がペットを飼う高齢者世帯を定期的に訪問し、ペットの診察を行ったりしているそうです。"}, {"k": "q", "t": "アナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.ペットを飼う高齢者の割合"}, {"k": "ch", "t": "2.ペットを長生きさせる工夫"}, {"k": "ch", "t": "3.獣医が不足している地域の状況"}, {"k": "ch", "t": "4.ペットを飼う高齢者への支援体制"}]}, {"head": "テレビである会社の人事部長が話しています。", "lines": [{"k": "spk", "s": "女", "t": "日本では正規雇用の場合、副業を禁止している会社が多いんですが、わが社では、社員に多角的な視点を持ってもらおうと、2年前から本業以外に仕事を持っことを推奨しています。今や社員の三分の二が、退社後や週末になんらかの仕事にかかわっています。多様な経験をしていることで、以前と比較して、会議で自発的かっ活発に意見が出されるようになり、業績の向上にもつながっていると思います。また個人個人が時間というものの価値を自覚したことで、残業時間も削減されました。"}, {"k": "q", "t": "部長は何について話していますか。"}, {"k": "ch", "t": "1.副業を禁止する理由"}, {"k": "ch", "t": "2.副業が本業にもたらす効果"}, {"k": "ch", "t": "3.労働者の権利を守る取り組み"}, {"k": "ch", "t": "4.労働時間を削減する努力"}]}], "2017-12": [{"head": "テレビで緑市の職員が話しています。", "lines": [{"k": "spk", "s": "女", "t": "緑市ではここ数年、伝統的な建築技法で作られた古い民家を購入したり、借りたりする人が急増しています。家の外観や構造を維持しつつ、中を改築して、住居や店舗などにするんですね。古い建築物には独特な味がありますし、放置されていた空き家が再生することで、防犯上の不安も解消されます。また将来的には、そのような民家が多い地域で、昔の町並みを復元し、それを観光資源として、町を活性化させることも検討しています。改築にはそれなりに手間もかかりますが、それを上回るものがあると言えそうです。"}, {"k": "q", "t": "市の職員は、何について話していますか。"}, {"k": "text", "t": "1古い民家を改築しないで保存する意義2古い民家の住みやすさ3古い民家を再利用するメリット4古い民家を再生することの難しさ"}]}, {"head": "電話で女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "はい。青空自動車の伊藤です。"}, {"k": "spk", "s": "男", "t": "もしもし、いつもお世話になっております。太陽製作所の渡辺です。"}, {"k": "spk", "s": "女", "t": "あ、渡辺さん、お世話になっております。"}, {"k": "spk", "s": "男", "t": "昨日ご注文いただきました部品の納期と価格の件でご連絡しました。実は、このところの原材料や原油価格の高騰で、部品の生産が難航していまして。大変申し訳ありませんが、今月中旬という納期のご希望にはお応えできそうにないんですが。"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "ただ、めどは立ちつつありますのて、今月末にはお届けできそうです。それから、取引価格の値引きのご要望ですが。"}, {"k": "spk", "s": "女", "t": "はい。"}, {"k": "spk", "s": "男", "t": "こちらも、原材料費が値上がりしているため、大変厳しい状況ではございますが、納期の件、ご了承いただけましたら、ご希望通りお取引させていただきます。"}, {"k": "spk", "s": "女", "t": "わかりました。では社内で検討して、後ほどご連絡いたします。"}, {"k": "q", "t": "男の人は、部品の納期と価格について、何と言っていますか。"}, {"k": "text", "t": "1納期も価格も希望に応えられる2納期も価格も希望に応えられない3納期だけ希望に応えられる4価格だけ希望に応えられる"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "日本では古くから「ツバメが低く飛ぶと雨が降る」と言われてきました。今でこそ、これは科学的に明らかになっていますが、あっ、つまり、雨雲が近づき、湿度が上がると。ツバメのえさとなる羽虫が高く飛べなくなるためなんですね。でも、まだ気象学もない時代に目の前の自然現象から一定の法則を見出す当時の人の力には、感心させられます。昔は、天候や天気が人におよぼす影響が今より大きかったことも理由なのでしょうが。微かな変調から真実を発見する能力の高さは現代の私たちとは大違いですね。"}, {"k": "q", "t": "女の人が伝えたいことは何ですか。"}, {"k": "text", "t": "1気象学の進歩の速さ2昔の人の観察力の鋭さ3気候や天気が生物に与える影響4言い伝えを検証することの大切さ"}]}, {"head": "大学で先生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "昆虫の中には、例えば、蝶や蜂、蝉など、幼虫のころと成長した後で、その形態が大きく異なるものがいます。これらの昆虫は、幼虫の時は、くびれのない長い胴体に短い足といった原始的で単純な外見をしているのですが、これは、成長するための栄養を体内にできるだけ多く取り込み、蓄えるのにとても適した形なのです。しかし、いったん成長し、生殖能力が備わると、今度は繁殖が生存の目的となるため、交配相手を有利に探せるよう、より広い範囲を移動することができる羽を手に入れるというわけです。"}, {"k": "q", "t": "先生の話のテーマはなんですか。"}, {"k": "text", "t": "1昆虫の種類による移動範囲の違い2昆虫の成長に必要な栄養3昆虫の繁殖の仕方4昆虫の形の変化とその理由"}]}, {"head": "新入社員の研修会で、講師が話しています。", "lines": [{"k": "spk", "s": "女", "t": "小売店の多くでは、客が店の中をどのように歩くかを意識して、店内のレイアウトを決めています。例えば、スーパーの多くでは、客に店内を一周歩かせるために、入り口から壁ぞいにぐるっと購買率が高い食品を陳列しています。そうすることで、客は自然と長い距離を歩くことになり、目的以外の商品も目にしたり手に取ったりする機会が増え、それが購入の促進につながるのです。これはスーパーに限ったことではなく、えー、例えば、家電販売店でも同様のことが言えますが、家電販売店の場合は、スーパーとは多少異なり、客の関心が高い商品を店の入り口から遠い奥に置くことで、売り上げアップを図っているところが多く見受けられます。"}, {"k": "q", "t": "講師の話のテーマはなんですか。"}, {"k": "text", "t": "1収益を上げるための商品の配置2買い物をしやすくするための店の工夫3購買率が高い商品の見分け方4スーパーと家電販売店の接客の違い"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、生活排水などによって海に過度な栄養成分が流入すると、微生物の増殖が進み、海水の汚染が進行します。そこで、微生物増殖の抑制が重要なんですが、その助けとなっているのが、かきという貝です。フライにしたり、鍋料理に入れるとおいしいですよね。かきは海中の微生物を主な餌としていて、海水を体内に取り込んでは、餌を濾しとり、澄んだ水を吐き出すんです。一匹につき、一日200リットルもの海水を濾過するので、濁った海水の掃除屋としてかきを養殖している地域もあります。まあ、こういう環境で育ったかきは、食用には向かないそうですがね。"}, {"k": "q", "t": "先生は、何について話していますか。"}, {"k": "text", "t": "1かきの成育に適した水質2かきによる水質改善作用3かきの養殖に必要な水の量4微生物の増殖によるかきの危機"}]}], "2018-07": [{"head": "会社で女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "見て見て。昨日新しいスカーフを買ったの"}, {"k": "spk", "s": "男", "t": "おお、きれいな色だね"}, {"k": "spk", "s": "女", "t": "ありがとう。週末に街を歩いてて見つけて、つい買っちゃった"}, {"k": "spk", "s": "男", "t": "衝動買いしたのか。要らないもの買って、後悔したりしたことない~"}, {"k": "spk", "s": "女", "t": "うん、実は、直感で選んだ服ほど長く着てるんだよね。いろいろ考えてから買うこともあるんだけど、そういうのはそこまで愛着がわかないっていうか。"}, {"k": "spk", "s": "男", "t": "そういわれると、ぼくも思い当たることあるなあ。"}, {"k": "spk", "s": "女", "t": "その場で即断できちゃうものって、それだけひきつけるパワーがあるんじゃない。人にも一目ぼれというか、会った瞬間に何か感じる人っているでしょう。それと同じ。"}, {"k": "q", "t": "女の人が言いたいことは何ですか。"}, {"k": "ch", "t": "1.必要がないものを買うと後悔する"}, {"k": "ch", "t": "2.急いで買うと失敗する"}, {"k": "ch", "t": "3.迷わずに買ったものは飽きない"}, {"k": "ch", "t": "4.よく考えて買ったものは長く使える"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "トラックに生鮮食料品や雑貨などを載せて移動しながら販売する移動式サービスがありますね。買い物に不便な場所などで非常に喜ばれていますが。実はいくっかの銀行でも同様のサービスを始めています。トラックにATMの機械を積んで窓口業務をする人もいっしょに移動するのです。もともとは災害時の対応として始められたものでしたが、銀行のない地域に住んでいる人の不便だという声を受けて、災害時以外にも、銀行のない地域を回るようにしたとのことです。今はまだ限られた地域での運用ですが、これらの銀行としては、サービスを向上させ、ほかの銀行との差別化を図りたいと考えているそうです。"}, {"k": "q", "t": "アナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.いろいろな移動式サービスの種類"}, {"k": "ch", "t": "2.災害に備えた地域の取り組み"}, {"k": "ch", "t": "3.銀行が移動式サービスを始めたこと"}, {"k": "ch", "t": "4.銀行同士の競争が激しくなっていること"}]}, {"head": "テレビでみどり市の市長が話しています。", "lines": [{"k": "spk", "s": "男", "t": "わがみどり市の桜並木は多くの観光客が訪れる大切な観光資源です。ところが、昨年の春部の桜に病気が発生しています。何とか伐採せずにすむ方法を模索しておりましたが、ほかの木への感染が予想以上にはやく、対応が後手に回ってしまいました。毎年開催している桜祭りも、今年は中止を検討しています。新しく木を植えるためにも、木を切ることは避けられないと考えております。"}, {"k": "q", "t": "市長は何について話していますか。"}, {"k": "ch", "t": "1.桜祭りに来る客を増やすための対策"}, {"k": "ch", "t": "2.桜の木の病気に対する対応"}, {"k": "ch", "t": "3.桜の木を切ることに反対する運動"}, {"k": "ch", "t": "4.桜の木を新たに植える取り組み"}]}, {"head": "大学で先生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "麦は昔から世界各地で様々な食品の原料として使われてきました。最近ある研究チームが世界各地の野生の麦と栽培されている麦のDNAの配列を比較しました。その結果現在世界で栽培されている麦がヨーロッパとアフリカに挟まれた地域の野生の品種に近いことを突き止めました。もともと野生の麦は実が落ちやすく栽培には向かないのですが、実が落ちにくい突然変異の麦がこの地域で生まれ、それが世界各地で栽培されるようになったと考えられます。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.現在栽培されている麦の始まり"}, {"k": "ch", "t": "2.麦に関する研究の展望"}, {"k": "ch", "t": "3.麦を分類する方法"}, {"k": "ch", "t": "4.麦の突然変異の仕組み"}]}, {"head": "取引先の会社で広告代理店の女の人がプレゼンテーションをしています。", "lines": [{"k": "spk", "s": "女", "t": "このたびは御社の広告キャンペンをお任せいただきまして、ありがとうございます。来期はウエプを中心に行う方向でお考えとのことでしたが、私どもとしましては、この商品の購入者が多く利用するメディアを中心にしたキャンペーンをご提案したいと思います。ウエプは、またはテレビコマーシャルも効果的な広告媒体ではあります。ただ御社の商品を利用している方の多くは高齢の方です。ほかの世代に比べて、新聞をよく読んでいます。もちろん予算を分配してウエプやテレビコマーシャルを製作することも考えられますが、限られた予算を集中させたほうが効果を期待できると思います。"}, {"k": "q", "t": "女の人は広告についてどのようにすべきだと言っていますか。"}, {"k": "ch", "t": "1.ウエプを中心に行うべきだ"}, {"k": "ch", "t": "2.ウエプとテレビで行うべきた"}, {"k": "ch", "t": "3.新聞とウエプとテレビで行うべきた"}, {"k": "ch", "t": "4.新聞に絞って行うべきだ"}]}, {"head": "動物保護団体のイベントで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "犬を引き取りたいけど、自分が年をとっていて、いつまで面倒を見られるかわからないから無理だと、嘆くのを聞きますが、そんなことはないと思うのです。私は犬が大好きで、これまでこちらの団体から十匹以上を引き取ってきました。皆捨てられて保護された犬たちです。私も70をすぎ、何匹も面倒を見ることはできませんから、いつも一匹ずっ向き合っています。なのに、なぜ10匹もと思われますよね。それは高齢や病気の犬を選んで引き取っているからです。もちろんかわいい子犬を見て引き取りたいと思ったことはあります。でも、70をすぎた私が子犬を引き取ったら、その犬がまた一人ぼっちになる可能性もありますからね。そんな無責任なことはできません。それなら、私でもしつかりと役割を果たせる犬をもらいたい、そういうことです男の人が言いたいことは何ですか。"}, {"k": "ch", "t": "1.無責任に犬を捨ててはいけない"}, {"k": "ch", "t": "2.高齢者に合った動物保護の仕方がある"}, {"k": "ch", "t": "3.子犬も高齢の犬も同様に保護すべきだ"}, {"k": "ch", "t": "4.犬は高齢者に癒しを与えてくれる"}]}], "2018-12": [{"head": "旅行関連のイベントで旅行会社の男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "空港や旅先での荷物の紛失・盗難、不安ですよね。我が社では新たに携帯電話と連動した旅行用かばんを開発しました。携帯から3Om離れると双方で警告音が鳴り、事態を知らせます。万が一、紛失もしくは持ち去られたとしてもGPS発信機が搭載されているので携帯から位置を把握、追跡できます。ただ、盗難の際は危険を伴うこともあるので自力での無理な追跡はくれぐれもなさらないように男の人は主に何について話していますか。"}, {"k": "ch", "t": "1.新しく開発された製品の機能"}, {"k": "ch", "t": "2.空港でよく起きている事件"}, {"k": "ch", "t": "3.かばんの安全な持ち方"}, {"k": "ch", "t": "4.旅先でトラブルから身を守る方法"}]}, {"head": "会社で男の人と在宅勤務を体験した女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": ""}, {"k": "spk", "s": "前田さん", "t": "人事部が募集し、た在宅勤務体験や。、みたんだ。、?制度を取り入れるかどうかの試験的なものだって聞いたけど"}, {"k": "spk", "s": "女", "t": "うん。たった1週間だけどね。いつも高齢の父を一人家に置いて仕事に出るのは気掛かりだったんだけど、それがなくて仕事に打ち込めた。早く制度化されないかな。"}, {"k": "spk", "s": "男", "t": "働きやすくなる人いるだろうね"}, {"k": "spk", "s": "女", "t": "だけど体験してみて、そう簡単に導入ってわけにはって思ったのも事実かな。"}, {"k": "spk", "s": "男", "t": "え、そうなの?"}, {"k": "spk", "s": "女", "t": "オフィスなら些細なことでもすぐ誰かに気軽に聞いたりできるでしょ?家でとなると、いちいちメールや電話で聞くの憚られて、他の体験者もいいことばかり報告したわけじゃなさそうだし。ますはそういうのを1つずつクリアしていかないとってこと"}, {"k": "spk", "s": "男", "t": "体験した人じゃないとわからないことってあるもんだよねざいたくきんむせいどどうにゆう在宅勤務制度の導入について、女の人はどう考えていますか。"}, {"k": "ch", "t": "1.問題点はなく、早く導入した方がいい"}, {"k": "ch", "t": "2.問題点はないが、導入しなくてもいい"}, {"k": "text", "t": "かいせんどうにゆう"}, {"k": "ch", "t": "3.問題点を改善してから導入したほうがいい"}, {"k": "ch", "t": "4.問題点があり、導入自体をやめた方がいい"}]}, {"head": "講演会で建築家が話しています。", "lines": [{"k": "text", "t": "にゆうねんけいかくじゅんびさんどう"}, {"k": "spk", "s": "男", "t": "物を作るのに大切なことは入念な計画と準備であると言った人がいます。私も大いに賛同そうぞうてきします。ただし、それは創造的なものでない場合に限ります。発想を形にするには何度も壁かていえいようはってんにぶつかって、失敗してはやり直す。その過程が栄養となり、アイティアを発展させるのでげんだいにゆうねんじゅんびす。現代人はとかく入念な準備に重きを置き、それが不完全なまま、次の工程に進むことちゅうちょしつばいものづくひつようかていおそを躊躇しがちですが、失敗は物作りにおける必要な過程なのですから恐れることはないのです。"}, {"k": "q", "t": "建築家は何について話していますか。"}, {"k": "ch", "t": "1.物作りの準備でやっておくべきこと"}, {"k": "ch", "t": "2.物作りで個性を生かすことの必要性"}, {"k": "ch", "t": "3.計画的に物を作ることの重要性"}, {"k": "text", "t": "そうぞうてき"}, {"k": "ch", "t": "4.創造的なものを作るのに大事なこと"}]}, {"head": "会社で社長が新たに管理職になった人たちに話しています。", "lines": [{"k": "text", "t": "かんりしよくどうりようなかまかんり"}, {"k": "spk", "s": "男", "t": "みなさん。管理職になると今まで同僚だった仲間が部下に、友人、ライバルが自分の管理そしきがわ下に入るわけです。厳しく注意をしたり、組織の側に立ってものを言わなければならなかったりと、これまで通りの付き合いとはいかないこともあるてしよう。そういった中でも、管みちび理職というのは部下を導き、しつかり結果を出さなくてはなりません。部下一人ひとりのてきせいひょうかやる気を引き出し、公平にかっ適正に評価するよう務めること。今、私が話したことは、しっかり肝に銘じておいてください。"}, {"k": "q", "t": "社長は何について話していますか。"}, {"k": "text", "t": "しようずっあ"}, {"k": "ch", "t": "1.部下との上手な付き合い方"}, {"k": "ch", "t": "2.部下との間で起きやすいトラブル"}, {"k": "text", "t": "ほうさく"}, {"k": "ch", "t": "3.部下のやる気を引き出す方策"}, {"k": "ch", "t": "4.部下を持つにあたっての心構え"}]}, {"head": "テレビで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "キャッチボールには必ず相手が必要ですね。相手が上手にポールを受け取ってくれると投げる方も気持ちよく投げられるものです。会話もこれと同様て、受け取る人がうまく受け答えしなければギクシャクしてしまいます。受け答えには、うんうん、それで、など青信号のようにそのまま話を続けてという意味のものもあれば、どういう意味?、ちょっと待って、など途中で相手の話を止める黄色や赤の信号の役割を果たすものもあります。話している人あおしんごうかげんあいづちに対して、いつも青信号がいいかというと、そうではありません。いい加減な相槌や一本調子の対応では話す人も話す意欲を失ってしまいます。黄色や赤の信号もうまく利用して、話の交通整理をしていくと相手も気持ちよく話せるでしょう。"}, {"k": "q", "t": "女の人は何について話していますか。"}, {"k": "ch", "t": "1.スポーツにおけるコミュニケーションの重要性"}, {"k": "ch", "t": "2.いい聞き手になる方法"}, {"k": "ch", "t": "3.交通ルールの果たす役割"}, {"k": "ch", "t": "4.人前でわかりやすく話をする方法"}]}, {"head": "ラジオで専門家が車の自動走行について話しています。", "lines": [{"k": "spk", "s": "女", "t": "近年、高齢者による自動車運転の誤操作、例えばアクセルとプレーキの踏み間違いなどが多発しています。こうした中、自動走行への期待が高まり、開発が進んでいるわけですが、何が自動で出来て、何が出来ないのかなど、不透明なところがあり、多くの人が自動走行というものを正確には捉えていないようです。現状では完全に自動で走るというところまでは行っておらず、あくまでも運転手の補助にすぎないのですが、そうとは思っていない方も多いんじゃないでしょうか。正しい情報、知識の共有が待たれます専門家は車の自動走行についてどんな意見を述べていますか。せいげん"}, {"k": "ch", "t": "1.高齢者の利用は危ないので制限すべきだ"}, {"k": "ch", "t": "2.一部安全性に信用できないところがある"}, {"k": "ch", "t": "3.人々の認識にずれがあり、是正が必要だ"}, {"k": "text", "t": "ぎじゅっ"}, {"k": "ch", "t": "4.実現に向けては技術に多くの課題が残る"}]}], "2019-07": [{"head": "大学の先生が授業で話しています。", "lines": [{"k": "spk", "s": "女", "t": "コンピューターが話し言葉を瞬時に他の言語に翻訳してくれる音声・翻訳技術が向上し、外国語ができなくても、異なる言語を話す人とのコミュニケーションが可罷になってきました。では、こんな時代に外国語を学ぼうという人はいるでしょうか。他の言語を学ぶことはその文化を知ること。ひいては、自分の言葉や文化を捉え直すきっかけともなります。未知の言語に触れて初めて気づくことも多いでしょう。機械任せにせず、学んだ言葉でコミケーションが取れることは、喜びであり、人生を豊かにしてくれるものです。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.音声翻訳技術の可能性"}, {"k": "ch", "t": "2.コミュニケーションカの高め方"}, {"k": "text", "t": "外国芸一口五ロ学との意味"}, {"k": "ch", "t": "4.自分の言二暴を見直すことの重要性"}]}, {"head": "留守番電話に、自動車の修理会社の人からメッセージが入っています。", "lines": [{"k": "spk", "s": "男", "t": "森田カーズの渡辺です。ご依頼のあったお車のェアコンの修理の件でお電話しました状態を確認しまして、やはり一部部品を取り替えることになりましたが。あいにく在庫を切らしておりまして、メーカーから最りせております。ええ、お車の状態も確認させていただきましたが、エンジンやタイヤなどのコンディションは良好でした。先日、あさっての午前中にお引渡しとご案内しましたが、部品が届くまであと数日かかる見込みです。改めてご連絡差し上げますこのメッセージで言いたいことは何ですか。"}, {"k": "ch", "t": "1.車の修理が完了した"}, {"k": "ch", "t": "2.車に修理が必要なところが見つかった"}, {"k": "ch", "t": "3.車の修理完了が予定より遅れる"}, {"k": "ch", "t": "4.部品を交換してもいいか教えてほしい"}]}, {"head": "テレビで、レポータが市役所の男の人にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "今日は川田市で移往者への支援を担当していらっしやる鈴木さんにお話を伺います。川田市に移往してくる人が増えているそうですがかわたしいじゅう"}, {"k": "spk", "s": "男", "t": "ええ、人口減少の解決策として、十年前から、県外から川田市に移住してくる人を積極的に支援しているんですが。最近は、三十代から四十代の方が、ご家族で移住してくるケースが増えてきています"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "以前は地方移住というと、退職後、田舎でのんびり暮らしたいという人が多かったんですが。今は就業を希望する人が多く、移住後の仕事を見つけられるかどうかが課題となっています彩往してよかったと思っていただくには、済的に安定した生活が必要ですから。"}, {"k": "spk", "s": "女", "t": "確かにそうですね。"}, {"k": "spk", "s": "男", "t": "市としても、さまざまな面からサポートをしています。川田市のような経済規模の小さいところでは、業や職に限りはありますが、積極的に仕事を旋しています。飲食店などご自身で起業するケースも少なくないです。そういう方には、地元の生産者や商店街の方を紹介したりすることもあります。"}, {"k": "spk", "s": "女", "t": "へえ、そうなんですか。地元の活性化にも繋がりそうですね。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.川田市の人口減少による経済への影響"}, {"k": "ch", "t": "2.川田市に移住する人のための曼覆"}, {"k": "ch", "t": "3.川田市に移住する人の高齢化"}, {"k": "ch", "t": "4.川田市への移住者に適した仕事"}]}, {"head": "市民講座で講師が話しています。", "lines": [{"k": "spk", "s": "女", "t": "まだ食べられるのに捨てられてしまう食品を食品ロスといいます孟痛プロセスや各家庭で大量に発生していて、今大きな問題となっています。食品メーカーやスーパーなども、の問題に真薊に取り組んでいますが。その対策の一つが員味期間の長期化です。員味期間が短いために冗れ残ったり、廃彙されたりすることを防ごうというのです。メーカーは食品の少化の兀凶となる馥素を排爍しようと、食品の製ヱ種に工夫をしたり、谷器を改莨しうれのたりしています。また、スーパーなどでは、員味期限間近の商品を格安で販売し、売残りが出ないようにしているところも増えています。"}, {"k": "q", "t": "講師は何について話していますか。"}, {"k": "ch", "t": "1.食品ロスを防ぐための企業の努力"}, {"k": "ch", "t": "2.員味期間に対する箔費者の意識"}, {"k": "ch", "t": "3.酸素が食品を劣化させる仕組み"}, {"k": "ch", "t": "4.新しい食品容器の開発"}]}, {"head": "講演会で男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "山菻は自然のまま放置するのではなく、木を切に夜採したり、保護したり、常時手入れタゆうじをする必要がありますが、近年林業に従事する人が高齢化しています。林業の仕事は地道で危険も伴うイメージがあるため、後継者が見つからないという現叔があり、このままでは衰退していくことが懸念されます。林業のイメージを変え、力を広くアピールしていくことが今後の課題てしよう。林業を支える若者を増やし、育成していく必要があります。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.山林を管理する方法"}, {"k": "ch", "t": "2.林業における羸悚の必要性"}, {"k": "ch", "t": "3.林業の後継者育成の方法"}, {"k": "ch", "t": "4.若者にとっての林業の魅力"}]}, {"head": "テレビでアナウンサーが東電機という会社について話しています。", "lines": [{"k": "spk", "s": "女", "t": "電襪メーカーの東電機がパソコン事業のすべてを霧提剏している西山に移行する方針を打ち出しました。東電機は五年前、パソコンの開発製造で急成長中の西山と業務提携を開始しました。以来、パソコンの製造は西山の工場に委託してきましたが、今回、パソコンの営戦略は西山のほうが優れていると莉断し、製造だけでなく、嶄製品の企画から販売までのすべてを西山に委ねる方釜十です東電機としては今まで弱だった海外向けパソコンの開発も、西山のノウハウで加速したい考えです。"}, {"k": "q", "t": "アナウンサーは東電機の何について話していますか。"}, {"k": "ch", "t": "1.嶄製品の販売開必"}, {"k": "ch", "t": "2.業務提携している会社との合併"}, {"k": "ch", "t": "3.パソコン事業の方針転換"}, {"k": "ch", "t": "4.海外でのパソコンの製造"}]}], "2019-12": [{"head": "テレビで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "近年、海外に出かける若者が以前より減っているそうです。アルバイト代やポーナスをもら韋ちよきんっても将来に備えて貯金する堅実派が多いとか、計画的でいいと思いますが、ちょっと残念な気がします。わたしは20代のころ、一年かけて世界一周旅行に出かけました。体ーっでし,うきよう言葉も小教も違う、いわゆる異文化の中に飛び込んでいったんです。見るもの、出会う人、すべてが嶄蘚でわくわくする一方、コミュニケーションを取ることの難しさもしたものです。こうした若い時の異文化体験は人を大きく成長させ、その後の人生の糧となります。若い人には、将来の自分に發資してほしいと思います。"}, {"k": "q", "t": "女の人は若い人に伝えたいことはどのようなことですか。"}, {"k": "ch", "t": "1.将来に備えて貯するべきだ"}, {"k": "ch", "t": "2.確実な發資の方法を学ぶべきだ"}, {"k": "ch", "t": "3.若い時の外国語学習は大切た"}, {"k": "ch", "t": "4.若い時の異文化体験は大切だ"}]}, {"head": "会社で男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "僕、ニュースはいつもインターネットのニュースサイトで見てたんだけど、たまに駅で朝刊を買って読んでるうちに、新聞に目覚めちゃって、十年ぶりに今はうちでとってるんた"}, {"k": "spk", "s": "女", "t": "へえ、インターネットのほうが、すぐ記事を検索できるし、便利じゃない?"}, {"k": "spk", "s": "男", "t": "まあ、そういう愉もあると思うけど、ある時、自分から見ようとしないニュースの中に見落としとか思わぬ播い惕があるじゃないかって思って面だといくつもの記事が同時に見渡せるし、片隅にふと気になるニュースを見つけたりして、記事のほうから目に飛び込んでくるっていうか。"}, {"k": "spk", "s": "女", "t": "確かに、インターネットのニュースサイトだと、記事とのそういう出会い方はね。"}, {"k": "spk", "s": "男", "t": "それに、各紙が情の審に責任をもって発信しているわけだから、ネットの情がすべて信頼できないとまでは言わないけど、その点もね。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.改めて新聞を読むことにしたわけ"}, {"k": "ch", "t": "2.インターネットニュースの便利さ"}, {"k": "ch", "t": "3.毎日新聞を読むことの大切さ"}, {"k": "ch", "t": "4.おすすめのニュースサイト"}]}, {"head": "ラジオでアナウンサーが話しています。", "lines": [{"k": "text", "t": "りゆフこっか"}, {"k": "spk", "s": "女", "t": "海の歌や、真冬のレストランなどの流行歌で知られる田中一郎さんが亡くなりました。89かずかず歳でした。田中さんは多くの歌手に作品を提復し、数々の流行歌を笙み出しました。まさに言葉の芸術家でした。作品はどれも力強く、言葉の一つ一つが人々に勇気や希望を与えてくれました。その作品はこれからも多くの人々に歌い継がれていくでしょう。何についてのニュースでしたか。"}, {"k": "ch", "t": "1.筰豪が亡くなったこと"}, {"k": "ch", "t": "2.作詞家の一生"}, {"k": "ch", "t": "3.流行歌の歌詞"}, {"k": "ch", "t": "4.流行歌の蒋徴"}]}, {"head": "テレビでアナウンサーが人工知能の専門家にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "最近、人工知能という言葉をよく耳にするようになりました。人工知能というのは大量のデータを積した機械に推論、学習など人間の知能の動きに近い能力を持たせようとするものですが。"}, {"k": "spk", "s": "男", "t": "ええ。製造物流から高齢者の介護まで幅広く役皿てられてますし、尨険な現場ての作業なんかも人工知能を搭載したロボットが行ったりしてますね。"}, {"k": "spk", "s": "女", "t": "家庭で組み立てられるコミュニケーションロボットも話題になりましたよね。"}, {"k": "spk", "s": "男", "t": "ええ、人工知能が家族一人一人を認し、会話によって、家族のことを理解し、成長していくというものですね。暮らしを便利にする上では、車のカーナビや自動足行なんかもそうで、生活の身近なところにも入ってきてます。"}, {"k": "q", "t": "話のテーマは何ですか。"}, {"k": "ch", "t": "1.人工知能はどのように霑用されているのか"}, {"k": "ch", "t": "2.人工知能はどうして必要なのか"}, {"k": "ch", "t": "3.人工知能は今後どうなっていくのか"}, {"k": "ch", "t": "4.人工知能はどんな問題を抱えているのか"}]}, {"head": "ラジオで女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "歴女っていう言葉を知っていますか。最近、歴史好きの女性を靂女って呼ぶんです。ほかにも、登山が好きな女性を山ガール、相撲好きを相撲女子って。それらの趣味は男性が好むものだと認識されていたからそこに進出していった女性たちをわざわざガールとか女子とかっけて呼ぶんでしょうね。今、このなになに女子っていう言葉がどんどん増えてきているように思います。逆に料理男子とか編み惕男子とか、なになに男子っていう言葉もいろいろ出てきてこちらも進出してきてるようです。おそらく、何年か先にはこの女子や男子というのも不要になるんでしょうね。"}, {"k": "q", "t": "女の人が言いたいことはなんですか。"}, {"k": "ch", "t": "1.歴史が趣味だという女性が増えていること"}, {"k": "ch", "t": "2.男性より、女性のほうが趣味が多いこと"}, {"k": "ch", "t": "3.趣味に男女差がなくなってきていること"}, {"k": "ch", "t": "4.趣味を持っ男性が少なくなったこと"}]}, {"head": "ラジオでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "春の訪れとともに山に積もった雪が溶け始めると、残った蕾と山肌が馬の形や鳥の形など様々の模様を作り出します。これを雪形と呼びます。雪形が見える地域では、昔から、馬が現れたら、田植えをするころだというように作物を作る目安にしてきました。このほかにも、農家の人々が目安とするものとして花の開花などがあります。地域によって目安にする花の種類は異なりますが、それらの花が咲くのを見て、野菜の種を撒くなどしてきたそうです。雪形も、花の開花も、気温などの条件に左右されており、昔から、自然の変化をうまく取り入れ、作物を作ってきたのです。"}, {"k": "q", "t": "アナウンサーは何について話していますか。"}, {"k": "ch", "t": "1.雪が積もった山の美しさ"}, {"k": "ch", "t": "2.天候と作物のできの関係"}, {"k": "ch", "t": "3.雪が花の開花に及ぼす影"}, {"k": "ch", "t": "4.筰暴の時期を見める愈"}]}], "2020-12": [{"head": "テレビで男のアナウンサーと教育評論家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "本日は鞍育論家の河さんにお話を伺います河さん先日、大学生の生活時間調査の結果が発表されましたね。"}, {"k": "spk", "s": "女", "t": "ええ。調査結果の中て電子を含む読を時間が1日に全くないと答えた大学生が5割に上ったという舎がありましたね。読書離れが加していると言えます。"}, {"k": "spk", "s": "男", "t": "そうですか。当くしよ"}, {"k": "spk", "s": "女", "t": "読書はしたいが時間がないと答えた学生が多かったようですね。最近の学生はサークルやアルバイトで忙しくなっているようです。生活費や受費がかさむと言うことでアルバイトの時間が年々増加していますし。と・くしよばな"}, {"k": "spk", "s": "男", "t": "読書離れは携帯電話やパソコンの日及も影響しているのでしょうか。"}, {"k": "spk", "s": "女", "t": "そのような意見もよく聞かれますね。まあ、今回の調査からは明確な関係は見られませんで"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "本が売れなくなり、出版業界も古労しているようです。恵考力をえるためにも学生のうちに哲学書や長編の文学筰品など読んで欲しいですけどね。"}, {"k": "q", "t": "教育評論家は何について話していますか。"}, {"k": "ch", "t": "1.大学生の滝況"}, {"k": "text", "t": "と・くしよじかんげんしよう"}, {"k": "ch", "t": "2.大学生の読書時間減少の背景"}, {"k": "ch", "t": "3.大学生の読書の目的"}, {"k": "ch", "t": "4.大学生が読む本の傾向"}]}, {"head": "会社で男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "うちの部署、毎月全体会があるんだけど、毎回長くてまいっちゃうよ。"}, {"k": "spk", "s": "女", "t": "そっか。仕切る人の手際の問題?"}, {"k": "spk", "s": "男", "t": "ん一、それは...要嶺よく進めるために主要メンバーの人たちが前もって打ち合わせをしてるんだ。だから手際は悪くないんだけど、会議になると籍局論が糾しちゃうん"}, {"k": "spk", "s": "女", "t": "そうなんだ。意見がいろいろ出て、まとまらないってこと?"}, {"k": "spk", "s": "男", "t": "ん一、って言うより、異羸を唱える人たちがただ反論するばっかりで、じや実際にどうしたらいいかって言うとこまで言わないから話が集約されていかない感じかな"}, {"k": "spk", "s": "女", "t": "なるほどね。それだとなかなか籍論が出ないかもね。"}, {"k": "spk", "s": "男", "t": "そうなんだよ。正論を言いたいだけの人もいて、結局皈拾がつかなくなるんだよね。"}, {"k": "spk", "s": "女", "t": "そうなんだ。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.自分の音の簽の問題点"}, {"k": "ch", "t": "2.理想的な会の進め方"}, {"k": "ch", "t": "3.会議の前の打ち合わせの必要性"}, {"k": "text", "t": "ナくわり"}, {"k": "ch", "t": "4.会議における自分の役割"}]}, {"head": "ラジオで作詞家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "皆さんはせつかく浮かんだアイデアを忘れてしまって悔しい思いをした事はありませんか僕なんかしょっちゅうなんですが、でも最近、それを克服しつつあるんです僕は筰詞する時、日常の中でふと言葉が出てくるタイプなんですが、そういう瞬間を逃さないようにすのちのちゃく一をるためにいつも小さいノートを持ち歩くようにしたんですよ。その時の思いつきが後々役皿つかもしれませんからね。最初は筰詞のためのノートだったんですけど、最近はそれだけじゃなくて、やってみたいこととか今月の目標とか思いついたことを何でも書き留めておくノートとして使っています。皆さんも1度お試しください。"}, {"k": "q", "t": "作詞家が伝えたいことは何ですか。"}, {"k": "ch", "t": "1.忘れ物をなくす方法"}, {"k": "ch", "t": "2.作詞をする方法"}, {"k": "ch", "t": "3.アイディアを思いっく方法"}, {"k": "ch", "t": "4.アイディアを忘れない方法"}]}, {"head": "和食のセミナーで食品会社の社員が話しています。", "lines": [{"k": "spk", "s": "女", "t": "味噌は味最をはじめ、和食に欠かせない調味料ですね。味噌には大豆味噌、米味噌、麦味噌といくっか種類がありますが、どの味噌も味汁なとに使う場合は加熱しすぎないようにすると香り良く作れます。味噌は発餐品ですが、発醇の過程て韲じる審りの成分は加熱することで気体化し、それカ嚊に届くことで香りとして感じられるんです味最汁も沸騰させてしまうとその成分が飛んでしまい、おいしさを感じさせなくなってしまいます。"}, {"k": "q", "t": "社員は何について話していますか。"}, {"k": "ch", "t": "1.和食における味最汁の役割"}, {"k": "ch", "t": "2.味噌の種類による香りの違い"}, {"k": "ch", "t": "3.味噌の発行のさせ方"}, {"k": "ch", "t": "4.味噌の香りの成分の特性"}]}, {"head": "テレビである病院の院長が話しています。", "lines": [{"k": "spk", "s": "男", "t": "うちの病院は廊下や病室に約300点の絵画を飾っています。昨年購入しましたが、費用もかかりましたので計画の段階では内部関係者から絵より医殯機器を購入すべきと言う意見もありました。ただ今年行ったアンケートでは、患者や家族の癒しになっているなど肯定的な反応が大半でした職賞にも心のゆとりが生まれています。さらに最近では近くの燹術夫學と連携したプロジ=クトも始めています。例えば職員も参加して待合室の窓カラスを装飾したり、患者さん尚けのアート教室や作品の展覧会を開徹したりしています。"}, {"k": "q", "t": "院萇は何について話していますか。"}, {"k": "ch", "t": "1.病院で芸術に触れる機会を作る試み"}, {"k": "ch", "t": "2.病院の経營を改髯する芳策"}, {"k": "ch", "t": "3.医療設備を売実させる必要性いりようせ?羅じうじつ"}, {"k": "ch", "t": "4.芸術を利用した病気の治療方法"}]}, {"head": "大学の考古学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "皆さんは遺跡発の窺塲を見たことがありますか発は地譖な筰の繰り遉しですが、世紀の大発見があった時にはニュースでも大きく取り上げられます。古い書惕の記述があっても実在したかどうかその真理が定かではないものがたくさんあります。しかし土の中に埋もれていた遺跡が新たに発掘されることで、ある節が証明されたり、逆に否定されたりします。歴史が書き換えられると言ってもいいでしょう。例えば、私が小学校の時に習った時代区分と最嶄の時代区分とはなっているものもあるんですよ。小さな器の欠から遥か昔のことがわかるなんて面白いと思いませんか先生は何について話していますか。"}, {"k": "ch", "t": "1.遺嶄の発掘方法の変化"}, {"k": "ch", "t": "2.古い書惕の保存技術の進歩"}, {"k": "ch", "t": "3.古い時代の文化の重要性"}, {"k": "ch", "t": "4.の桶の憙義"}]}], "2021-07": [{"head": "建築事務所で男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "小林さん、どう?この間契約したお客さんの家の設計、進んでる?"}, {"k": "spk", "s": "女", "t": "それが、困ってるんです。家のイメージがまだ固まっていらっしやらないみたいで・具体に決めようとしてもなかなか話が進まなくて・"}, {"k": "spk", "s": "男", "t": "ふーん。ん一、じゃ例えば、小林さんはどんな朝ご飯を食べたい?普段食べているのじゃなくて、理想の朝ご飯"}, {"k": "spk", "s": "女", "t": "え?突然ですね。そうですね、和食がいいです。白いご飯と味最汁に焼き魚とか"}, {"k": "spk", "s": "男", "t": "それをどんな部屋で食べたい?"}, {"k": "spk", "s": "女", "t": "ん一、朝日をたつぶり浴びながら食べたいですね。食卓は大きな窓に論した場所にあるといいですね。緑も見えると最高だな。あ、そうか。"}, {"k": "spk", "s": "男", "t": "うん、ちょっと角度を変えた質問を投げかけてみると、もっと具体に考えやすくなるんじゃないかな"}, {"k": "spk", "s": "女", "t": "なるほど、ありがとうございます。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.客の希望を聞き出す方法"}, {"k": "ch", "t": "2.理想の家の条件"}, {"k": "ch", "t": "3.食事をする部屋の設計"}, {"k": "ch", "t": "4.新しい家で食べたい朝ご飯"}]}, {"head": "テレビで女のアナウンサーがりんご農園の男の人にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "こちらの展園のりんごは品質の高さに定評があり、生靃量も安定していると伺いましたか、荷か特別なことがあるんですか。"}, {"k": "spk", "s": "男", "t": "やつばり1番は天候てしようね。1年の平気温が10度前優、年間水冨が少ないといったりんご栽培に譎した条件を満たしてるんですよ。"}, {"k": "spk", "s": "女", "t": "なるほど。でもそういった天候の場所は他にもあると思うんですが・"}, {"k": "spk", "s": "男", "t": "あとはここの土地ですね利やの混じった土壤なので、りんご羲培に向いているんです。うちはそういう条件が整った山の面を広い面積で持ってるっていうのはありますね。"}, {"k": "spk", "s": "女", "t": "なるほど。"}, {"k": "spk", "s": "男", "t": "りんごは作り過ぎると価格が下がるし、量が少ないと需要に応えられない。ビジネスとして考えると、なかなか計画通りにいかないのが難しいところです。うちでは栽培技術の改良にも取り組み、更に安定した量が出荷てきるようになってきました。"}, {"k": "q", "t": "男の人は何について話していますか。"}, {"k": "ch", "t": "1.この展園の歴史"}, {"k": "ch", "t": "2.この展園の将来の経營プラン"}, {"k": "ch", "t": "3.りんご羲培の嶄しい術"}, {"k": "ch", "t": "4.りんご峩店がうまくいっている要因"}]}, {"head": "テレビの情報番組で女の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "睡眠は記憶に似ているとよく言われます。覚えていなければならないことはすぐ忘れてしまうのに忘れたいことはなかなか忘れられない。眠ってはいけない時には居眠りしそうになるのに眠らなくてはいけないと思うと、どんどん目が冴えてくる。こういうことはよくあることです。でも実は目を閉してかにしていれば、それだけで体を休めることができるのです。ですから、ことさら眠る必要はないのだと気持ちを楽にすることが重要なのです。そうしていると不思羸と眠くなるものなんですよね。"}, {"k": "q", "t": "女の人はどんなことについて話していますか。"}, {"k": "ch", "t": "1.記憶力を高める方法について"}, {"k": "ch", "t": "2.記憶力と睡眠の違いについて"}, {"k": "ch", "t": "3.睡眠を促す工夫について"}, {"k": "ch", "t": "4.睡眠を妨げる環境について"}]}, {"head": "テレビで大学の先生が話しています。", "lines": [{"k": "spk", "s": "女", "t": "私は海沿いのカニがよく捕れる町で生まれ月ちました。カニの生態にも員味を持ちましたが、港の缶詰場で大量に廃彙されるカニの殻を見て、有効莉用てきないかと考えるようになりました。カニの殻の主成分にはを治したり、膚を健康に保ったりする効用があります。ただ、水に溶けにくいことが難魚で、なとへの利用は実現されていませんでした。私は試行錯誤の末、殻を熹て、不要な成芬を取り除き、細かく粉砕することで加主できるようにしました。現在は企業と協して、や花粧品など、様々な製品への利用法を研究しています。今年はカニの収穫量も多いので研究も進みそうです。"}, {"k": "q", "t": "先生は何について話していますか。"}, {"k": "ch", "t": "1.カニの缶詰を作る技術"}, {"k": "ch", "t": "2.カニの殻の成分の活用"}, {"k": "ch", "t": "3.カニの生態を調査する難しさ"}, {"k": "ch", "t": "4.カニの収量を高める研究"}]}, {"head": "テレビでサッカー選手が話しています。", "lines": [{"k": "spk", "s": "男", "t": "えー、私はこの度、現役生活に止符を打っことにいたしました。昨年、試合中に負街しおおしゅじゅっひっしりはびりみのしうばんてしまい、大きな手術を受けました。必死のリハビリが実って、今シーズン褄盤には何しゆっじようひがんゆうしようはとか試合に出場することができ、最後はチーム悲願の優勝を果たすことができましたチームとしては最高の結果を得て、この上ない感動を味わいましたが、佃人に満足のいくプレーができたかといえば、そうではありません。自身がのいくプレーができなくなった以上、今後継続していくことは難しいと感じました。怪我をして辛かった硺に支えかんしやてくれたファンやスタッフの方々、チームメイト、そして家族には感謝の気持ちでいつばいですサッカー選手は主に何について話していますか。けがなおふつきゆうしよう"}, {"k": "ch", "t": "1.怪我が治って復帰できた喜ひ"}, {"k": "ch", "t": "2.優勝した時の感動"}, {"k": "text", "t": "いんたいけついけいいせんしゆささひとびと"}, {"k": "ch", "t": "3.引退を決意した経緯"}, {"k": "ch", "t": "4.選手を支える人々の大切さ"}, {"k": "text", "t": "けいえいかいぎけいえいかいぜん"}]}, {"head": "ホテルの経営会議で女の人が経営の改善について話しています", "lines": [{"k": "text", "t": "しくはくきやくはんしようぎようせきけい、いかいせんひつようていあん"}, {"k": "spk", "s": "女", "t": "蓿泊客が減少し、業績が落ち込んでいる今、経營の改善が必要です。そこで提案したいのがホテル内にある置營レストランの見直しです。このレストランは食時以外は、りようけい、いふたんほとんど客の利用がなく、維持費ばかりかかり、経營の負担になっております。レストラン改襄などによる客の増加に期待するよりも飲餐専門の会紅と提携し、経費を怖える芳ダくさくが得策だと考えます。例えば、1階のレストランをファミリーレストランに委託し、しくはくきやく蓿泊客には朝食クーポンを渡して、そこを利用してもらうというのはどうでしょうか。ちく一いていかいたくさきこれなら置營レストランがなくともサービスの低下にはなりませんし、委託先にとってりようきやくかくしつそうほうもホテルの利用客が確実に自分の店の客になるので、双方にメリットがあると言えます。ていあん女の人は何を提案していますか。かいそちく一いせっち"}, {"k": "ch", "t": "1.レストランの改装"}, {"k": "ch", "t": "2.置營レストランの設置"}, {"k": "ch", "t": "3.雀の簽紅への去氈"}, {"k": "ch", "t": "4.蓿箔へのサービスの改髯"}]}], "2021-12": [{"head": "大学院の授業で先生が話しています。", "lines": [{"k": "text", "t": "しつけんぎじゅっしゃぼしゅうさいよううちゅうたいざい"}, {"k": "spk", "s": "男", "t": "今、宇宙で科学の実験をする技術者を募集しています採用されたら、宇宙に滞在し、しつけんたんとうよていおうぼしょしゅうりようくんねりひつようかがくちしき実験なとを担当する予定です。応募書は大学院を修了していて、訓練に必要な科学知識と技術力があり、他のメンバーとのコミュニケーション能力が高く、チームとして仕事を行うために、協調性と適応性が必要とのことです。先生は何について話しましたか。1実験の内容について2訓練の内容について3宇宙に滞在する期間について4応募者に求められる能力について"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "山川市は、近年、テレビアニメの舞台となったことで、県外から訪れる人が増えています。観光客の数はこの一年で5倍にもなりました。地域に大きな経済効果をもたらしましたが、一方で、週末は観光客で市内の路線バスは満員となり、道路も渋滞という状況が長く続いています。また、中には、アニメのモデルとなった美しい川を訪れて、遊泳禁止の場所で泳ぐ、河原で花火やバーベキューをしてゴミを片付けずに帰るといった人がいます。このような状況に対し、市民から苦情の声が寄せられ、市としても、頭を抱えているということですアナウンサーは何について話していますか。1観光客の増加で生じた問題2観光客を呼び込むための試み3観光客と市民の交流4観光客から寄せられた苦情"}]}, {"head": "講演会で建築家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "昔は、個人の家にも親戚や地域の集まりを行えるような広い部屋がよくありました。玄関を入ってすぐの場所に、客を通す部屋があることも一般的でした。その後、生活様式や社会の変化に伴って、新築の際に、そのような部屋を設けることはかなり少なくなりました。最近は、同じ家に住む家族の絆を大切にしたいと考える人が大きくなり、部屋と部屋の仕切りがない間取りにすることが増えています。お互いの時間を尊重しつつも、家族の気配を感じながら、過ごせるような住宅が多くなっています。"}, {"k": "q", "t": "建築家は何について話していますか。"}, {"k": "text", "t": "1地域による住宅の違い2客を迎える部屋の造り3人々が家で過ごす時間の増加4家の間取りの変化"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "雪やこんこ、犬は喜び、庭かけ回る。猫はこたつで丸くなる。と歌にも歌われていますが、犬はどうして雪が降ると、大喜びしてかけ回るんでしょう。実は、犬は雪だけじゃなくて、家にお客さんが来てもはしやぎますし。長く雨の日が続いてようやく晴れた日にも大はしゃぎします。つまり、環境が変わった時や、何か新しいできごとが起きた時、気分がこうようするのです。犬は私たちから見て、ちょっとしたことにもオーバーに反応すると言えるでしょう。男の人は主に何について話しましたか。1犬と猫の歌2犬の行動3犬と人の関係4犬と天気の関係"}]}, {"head": "テレビで女のアナウンサーと映画監督が話しています。", "lines": [{"k": "spk", "s": "女", "t": "今回の映画を拝見して感じたことなんですが、映画の中で使われている日常の生活音がとても印象的でした。"}, {"k": "spk", "s": "男", "t": "はい、その点は全体を通してこだわったところです。僕もこの映画の主人公のように、18の時に、田舎から東京に出てきたんですけど。初めて家族から離れて、周りにだれも喋り人がいない寂しさに襲われたんです。そんな時、近所の人たちの笑い声や、子どもの遊んでる声とかにすごく癒されたんですよ。"}, {"k": "spk", "s": "女", "t": "都会で一人暮らしをしていると、どうしても孤独になりがちですよね"}, {"k": "spk", "s": "男", "t": "そうなんです。そういう時に聞こてくる人の血が通った音っていうのは聞く側を癒してくれる力があると思うんです。"}, {"k": "spk", "s": "女", "t": "一方で現実ては隣の家の騒音がトラカレになることもありますよね。となり"}, {"k": "spk", "s": "男", "t": "ええ。自分の気持ちが落ち込んでる時は、隣から聞こえてくる掃除機の音とか、煩いなと思うこともあります。だから、意図的にそういうシーンも入れました"}, {"k": "spk", "s": "女", "t": "それもまたリアルで生きている人間がうまく表現されているところですね"}, {"k": "spk", "s": "男", "t": "そう評価していただいてありがたいです。生活音なんて些細なものだけど、それによって、人と人がつながっているんですよね。まあ、この映画を見終わった後、音の先にだれかが生きているんだなと、なんとなく感じてもらえたら、それで満足です。"}, {"k": "q", "t": "映画監督は何について話していますか。"}, {"k": "text", "t": "1映画の効果音の作り方2映画作りでこだわったところ3登場人物の人間関係4映画のあらすじ"}]}, {"head": "会社の会議で社長が社員に話しています", "lines": [{"k": "text", "t": "けいざいふきよう"}, {"k": "spk", "s": "女", "t": "今日は全国の支店長の皆さんに集まっていただきました。えー、最近の経済不況の中、我が社は安定した売り上げを維持していて、商品開発に力を注いできた成果が出ていると言えます。しかしながら、少子高齢化が進んでいる現状では、今後、国内市場が縮小することは回避しがたいと考えられます。実際、今年度の売り上げが予想したほどには伸びなかったことにその兆しが現れたと言えます。さらなる成長には市場の開拓が急務であると考え、海外展開を行うことにしました。そのための新しいチームも発足させます。それについては、この後説明があります。各支店の人員体制にも関わりますのでよろしくお願いします。"}, {"k": "q", "t": "社長は何について話していますか。"}, {"k": "text", "t": "1経営が悪化した原因。2国内向けの商品の開発3今年の売り上げの予想4今後の授業展開の方針"}]}], "2022-07": [{"head": "テレビでアナウンサーの男の人が文具メーカーの女の人にインタビューしています。", "lines": [{"k": "spk", "s": "男", "t": "文具メーカーの競争が激しい中、こちらの会社の文具はユニークで人気があるそうですね。"}, {"k": "spk", "s": "女", "t": "おかげさまで。特にノートやペンの開発に力を入れています。べテラン社員が中心になって商品の企画と開発を行っていた時期が長かったんですが、5年前から入社間もない社員のアイデアも積極的に取り入れようということになりました。そこで開発チームに新入社員を入れ、新入社員に企画案を出してもらうことにしました。経験が浅いため、発想するものの中には実現不可能だったり、一見くだらないと思えるものも多いんですが、その発想に対して、みんなで一緒に意見を出し合うことによって良いものに発展することもあります。"}, {"k": "q", "t": "文具メーカーの女の人は何について話していますか?"}, {"k": "ch", "t": "1.今後開発予定の商品"}, {"k": "ch", "t": "2.べテラン社員の企画力の高さ"}, {"k": "ch", "t": "3.売れる文具に必要な条件"}, {"k": "ch", "t": "4.新商品を生み出す方法"}]}, {"head": "会社で部長が話しています。", "lines": [{"k": "spk", "s": "部長", "t": "この度、わが社では本の要約サイトが利用できるように法人契約を結ぶことになりました。これは本の内容を短く要約して提供してくれるサービスです。社員のみなさんはサイト内の本の要約が読み放題となるわけです。サービスの対象となる本は、主にヒジネスや政治経済関連のもので、1冊分の内容が、4千字程度にまとめられています。つまり1冊につき、10分ほどで概要が分かります。営業先でお客様からのご要望を伺う際に、ビジネスに関する知識や、最新の情報が不足していると、せつかくのビジネスチャンスを逃すばかりか、お客様の信頼まで失いかねません。幅広い意識は武器だとこころえ、活用しましょう。"}, {"k": "q", "t": "部長は何について話していますか?"}, {"k": "ch", "t": "1.人気がある本の要約サイト"}, {"k": "ch", "t": "2.客へ提供する新しいサービス"}, {"k": "ch", "t": "3.効率的に仕事を進める方法"}, {"k": "ch", "t": "4.要約サービスの利用の勧め"}]}, {"head": "大学の就職説明会で、大学の女の職員がある会社の人事担当の人にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "森川産業、人事課の中山さんにお話を伺います。さっそくですが採用試験のグループディスカッションについてお話を伺いたいと思います。"}, {"k": "spk", "s": "男", "t": "弊社ではチームで仕事を進めることが多く、チームワークが大事になってくるため、二次試験でグループティスカッションを行っています。"}, {"k": "spk", "s": "女", "t": "二次試験では具体的に学生のどのような点を見ているのでしょうか。"}, {"k": "spk", "s": "男", "t": "一次試験の書類選考では分かりにくい集団の中でどんな役割を果たす人なのかを見ています。人間性やリーダーシップ、協調性などです。"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "グループティスカッションでは自分にとって詳しくない分野のテーマに当たることもあるかと思います。でも、私たちは学生の知識や専門性より、集団で結論を出すまでの過程を重視しています"}, {"k": "spk", "s": "女", "t": "では、テーマについて詳しくなくても心配する必要はないと。"}, {"k": "spk", "s": "男", "t": "そうですね。たとえ自分が詳しくない分野でも、グループとして最高の結果を出すために自分には何ができるのかを考えてほしいと思っています。"}, {"k": "spk", "s": "女", "t": "自分の役割を考えて、チームに貢献する姿勢というのは社会に出てから大切ですからね。今日は貴重なお話、ありがとうございました人事担当の人は何について話していますか?"}, {"k": "ch", "t": "1.採用選考の過程で重視していること"}, {"k": "ch", "t": "2.入社前に勉強してほしいこと"}, {"k": "ch", "t": "3.最近の就職希望者の傾向"}, {"k": "ch", "t": "4.チームでの結果の出し方"}]}, {"head": "講演会で消費者問題の専門家が話しています。", "lines": [{"k": "spk", "s": "男", "t": "近年、日本でもインターネット上で不用品などの売買取引をするオークションサイトが普及しています。一般の人も気軽に出品でき、定価よりも安い値段で手に入れられることが多いためです。その一方で、人気のある商品を買い占めて、高額で別の人に売るという転売を行ったりする場合があります。特に高額転売に関しては、一部の商品以外は現在取り締まる法律がありません。サイト側の自主規制に委ねられていますが、十分とは言えません。他にも、出品に関するガイドラインが十分整備されていないことや、受け渡し方法の取り決めなど、早急な改善が必要です。"}, {"k": "q", "t": "専門家はオークションサイトの何について話していますか?"}, {"k": "ch", "t": "1.買い手にとってのメリット"}, {"k": "ch", "t": "2.売買における禁止事項"}, {"k": "ch", "t": "3.新しくなったガイドライン"}, {"k": "ch", "t": "4.運営上の課題"}]}, {"head": "ガラス瓶の製造業のシンポジウムで、ある会社の女の社員が話しています。", "lines": [{"k": "spk", "s": "女", "t": "ガラス瓶は近年消費者の需要が低下し、30年前と比較するとほぼ半減しています。現在でもシニア世代は食品や化粧品の容器としてガラス瓶の高級感を重視する傾向がありますが、若い世代はプラスチック素材より高価で扱いにくいガラス瓶を敬遠しがちです。こうしたカラス瓶に触れる機会が少ない世代がシニアになると、需要は更に落ち込むと予想されますこの年代にも魅力を知ってもらえるよう、これからはカラス瓶をインテリアとして用いるなど、容器以外の用途で楽しむ方法を提案し、新しい価値を持っ商品作りに挑戦していくべきてはないでしょうか~女の社員はカラス瓶についてどんな話をしていますか?"}, {"k": "ch", "t": "1.今の若者に対する需要の開拓"}, {"k": "ch", "t": "2.素材自体の利点"}, {"k": "ch", "t": "3.容器としての利用価値の高さ"}, {"k": "ch", "t": "4.現在のシニア世代のニーズの拡大"}]}, {"head": "大学の授業で先生が話しています。", "lines": [{"k": "spk", "s": "先生", "t": "今日は地球温暖化、特に日本の気温上昇と気候の変化について考えます。大気中に含まれる水蒸気量は、気温の上昇とともに増加します。近頃では、温暖化の影響によって、水蒸気を多く含む湿った大気が発生しやすくなっています。この湿った大気が極端にに冷たい所に流れ込むと、大雪が起こりやすくなります。この現象が起こるのは、一部の山岳地域や内陸部に限られているのですが、それによる被害が出ており、近々政府もその対策に乗り出すとのことです。"}, {"k": "q", "t": "先生は、何について話していますか。"}, {"k": "ch", "t": "1.温暖化の原因が分かったこと"}, {"k": "ch", "t": "2.温暖化によって雪が降らなくなること"}, {"k": "ch", "t": "3.温暖化で雪の量が増えるメカニズム"}, {"k": "ch", "t": "4.温暖化に対する政府の対策"}]}], "2022-12": [{"head": ":文房具の会社で社長が話しています。", "lines": [{"k": "text", "t": "このところ新たなヒット商品が出せていません。既存の商品の売り上げは順調ですが、会社が飛躍するためには、新しいものを生み出す必要があります。伝統にしがみつかず、これまでにないものを提案することは新しい文化の創造だと言っても過言ではありません。みなさん、批判を恐れずにどんどん挑戦してください。今はパソコンで文章を書くことが当たり前になっていますが、昔は文字を書くといえば手だったわけです。つまり、今の当たり前は、昔は奇抜なものだったかもしれません。周囲に驚かれるようなものこそ、会社にとっては宝なのです。"}, {"k": "q", "t": "問い社長が言いたいことはなんですか。(正解:3)"}, {"k": "ch", "t": "1.会社の業績を回復させてほしい。"}, {"k": "ch", "t": "2.会社の伝統を大事にしてほしい。"}, {"k": "ch", "t": "3.新しいアイディアを出してほしい。"}, {"k": "ch", "t": "4.新しく開発した商品をヒットさせてほしい。"}]}, {"head": "テレビでアナウンサーが俳優にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "今日は現在公開中の映画『虹の山』に出演されている河本シンジさんにお話を伺います。河本さん、今回は山での撮影が多かったそうですが、何かご苦労ありましたか~"}, {"k": "spk", "s": "男", "t": "標高の高い場所での撮影ということで、体調管理には気を遣いましたね。無事に体調を崩さずに撮影を終えることができてほっとしました"}, {"k": "spk", "s": "女", "t": "そうですか。河本さんは主人公の登山家を取材するカメラマンの役、ですね~"}, {"k": "spk", "s": "男", "t": "はい。この役は、始めは山の知識がほとんどない設定なんですが、実は僕自身は登山が大好きで"}, {"k": "spk", "s": "女", "t": "あっ、そうなんですか。"}, {"k": "spk", "s": "男", "t": "ええ。最初にお話しをいただいた時から山での撮影を楽しみにしていたぐらいです。なので、山に慣れていないように振る舞うところは不自然にならないように特に意識しました"}, {"k": "spk", "s": "女", "t": "なるほど。"}, {"k": "spk", "s": "男", "t": "それから登山家の方々に伺った話も参考にして、登山の魅力が伝わるように、ということを心がけました"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "q", "t": "問い質問:俳優は何について話していますか。(正解:2)"}, {"k": "ch", "t": "1.今回の役を引き受けた経緯"}, {"k": "ch", "t": "2.役を演じる上で気をつけたこと。"}, {"k": "ch", "t": "3.山での撮影の面白さ。"}, {"k": "ch", "t": "4.登山家との交流の思い出"}]}, {"head": "ラジオでサッカー選手が話しています。", "lines": [{"k": "text", "t": "ピアノを弾くのが趣味だっていうと驚かれるんですが、子どもの頃7、8年習ってて、結構弾けるんですよ。他の楽器でもそうかもしれませんが、ピアノを引くのって意外に運動に通じるところがあるんです。集中力が求められますし、リズム感とか体全体で表現する感覚みたいなものが活性化されるというか、聞いてる時、どうすれば上達するかって考えながらやっていて、その点でもサッカーと通じるところがあるなと思います。野球選手にもピアノ習ってることがプレーに役立ってるって言ってる方がいましたね"}, {"k": "q", "t": "問いこの選手は何について話していますか。(正解:4)"}, {"k": "ch", "t": "1.スポーツ選手に人気の趣味。"}, {"k": "ch", "t": "2.ピアノを習い始めたきっかけ。"}, {"k": "ch", "t": "3.ピアノが上達する練習方法。"}, {"k": "ch", "t": "4.ピアノ演奏がスポーツと共通する声"}]}, {"head": "講演会で医者が話しています。", "lines": [{"k": "text", "t": "テレビなどでよく健康法や長生きの秘訣が紹介されますね。体にいいある食材を毎日食べるなど、誰にでも簡単にできる、と言って紹介されるものも多いです。試すこと自体は悪くありません。ただ、患者さんと話してるとそういった健康法が誰にでも効果があると思ってる方が多いと感じます。栄養の偏りや運動不足、あるいは元々の体質など、健康を損なう原因は人によって違います。ですから、例えば何かの栄養をとることか勧められていても、すでに十分に足りてる栄養だったら取る必要はないわけですテレビなどで取り上げられているものても、自分の状態に合ったものかどうかを見極めることが健康への第一歩なんです。"}, {"k": "q", "t": "問い医者は何について話していますか。(正解:3)"}, {"k": "ch", "t": "1.テレビで紹介された健康法の効果"}, {"k": "ch", "t": "2.誰にでも効果のある健康法。"}, {"k": "ch", "t": "3.健康法を取り入れる際の注音占"}, {"k": "ch", "t": "4.長生きしている人の体の特徴"}]}, {"head": "ある市の議会で議員が話しています。", "lines": [{"k": "text", "t": "東地区ては高層マンションの建設が計画されており、それに伴って、今後、学齢期の子どもが増えることが見込まれます。東地区の東小学校では、現在の教室数では対応できなくなると予想されています。また、校舎が築50年を経過しており、地震対策など必ずしも万全とはいえません。IT特別教室などの設備の拡充も必要になっています。こうした点を踏まえ、早急に建て直すことが求められます。市の財政も潤沢とは言えませんが、未来を担う子どもたちの教育は最優先課題と考え、関係費用を来年度予算に計上することを提案する次第です。"}, {"k": "q", "t": "問い議員が言いたいことはなんですか。(正解:2)"}, {"k": "ch", "t": "1.東地区の将来の子どもの数を予測するべきだ"}, {"k": "ch", "t": "2.東小学校を建て替えるべきた"}, {"k": "ch", "t": "3.教育内容を改革するべきた"}, {"k": "ch", "t": "4.市の予算を削減するべきだ"}]}], "2023-07": [{"head": "女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "中田さん、今年町内会の役員をやってるんですか?この間の街の夏祭りで係用をやっていましたよね。"}, {"k": "spk", "s": "男", "t": "うん、そう、街のゴミ拾い活動とか防災訓練とか、他の役員のみんなと協力して進めているよ。街について新しい発見があるし、それまで知らなかったような人とも話せるようになるから、いい刺激になってるよ。"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "新しいマンションが増える地域なんかでは前より近所付き合いはへっちゃたって聞くけどね。この辺は皆町内会の活動にも協力的だよ。夏祭り、木村さん家族で来ただよね。"}, {"k": "spk", "s": "女", "t": "はい、にぎわってましたね。"}, {"k": "spk", "s": "男", "t": "あれもポスター貼ったり会場の準備したり、いろいろ町内会でやって、まあ苦労することもあるんだけど来てくれた人たちが喜んでくれるとやっぱり嬉しいんだよね。"}, {"k": "q", "t": "男の人は何について話してますか?"}, {"k": "text", "t": "1町内会の役員のやりがい2町内会の祭りの面白さ3町内の人々の交流の減少4町内会での新しい取り組み"}]}, {"head": "テレビでホクメイ旅館の社長が話しています。", "lines": [{"k": "text", "t": "地方によっていろいろな方言が話されています。しかし、観光業、特に地元以外のお客様が多い旅館やホテルなどでは方言の使用を控えるというところも多いです。私どもの旅館では、以前から接客時に、お客様に楽しんでいただくために、この地方の方言を使っていますが、方言は暖かい感じがすると好評です。ただ方言だと、お客様に通じない時もあり、言い換えたりするなど工夫が必要ですが、様々な方に方言を楽しんでいただきたいですね。JLPT・N1・07/2023社長は方言についてどのように考えていますか?1方言の使用は客へのもてなしの一つだ2客に対して方言の使用は控えるべきだ3客の出身地の方言で話したい4客にこの地方の方言を使ってもらいたい"}]}, {"head": "テレビでアナウンサーの女がボクシングの選手にインタビューしています。", "lines": [{"k": "spk", "s": "女", "t": "ボクシングの山下選手に伺います。昨日の試合は残念でしたが、ご本人としてはいかがでしたか。"}, {"k": "spk", "s": "男", "t": "そうですね。初めは相手選手からの連続のパンチがすごかったんですけど、応援してくれているみんなに自分の倒れる姿を絶対見せたくないと思って、頑張りました。"}, {"k": "spk", "s": "女", "t": "最後までよく耐えましたね。"}, {"k": "spk", "s": "男", "t": "結果審判の判定で敗れはしましたけど、いくつかいいパンチもあたりましたし、最後まで攻める姿勢は貫けたんじゃないかと思っています。"}, {"k": "spk", "s": "女", "t": "地元やジムの練習仲間も、たくさん応援に来ていました。山下選手の戦う姿をみて勇気や希望をもらったという方も多いと思います。"}, {"k": "spk", "s": "男", "t": "はい、次の試合も粘り強くさらに勝ちにつながるよう頑張りたいと思います。皆さん応援ありがとうございました。"}, {"k": "q", "t": "選手は昨日の試合についてどうだったと言っていますか?"}, {"k": "text", "t": "1まったく攻めることが出来なかった    2最後は諦めてしまった3結果を含めすべてうまくいった      4諦めずに戦い抜いた"}]}, {"head": "テレビで農家の人が話しています。", "lines": [{"k": "text", "t": "なしのうかさいばいうちは梨農家です。この地域で栽培されている梨の品種はどれも甘くてみずみずしいのに加えて、大きさも一般の梨の二倍ぐらいあります。この地域ではどの農園でも土づくりにはこだわっています。うちの土づくりにもこだわっていますが、それだけでなく、実のひとつひとつに栄養が十分行き渡るように育てています。梨の花が咲いた後、幹から伸びる枝を整えて、枝の先が上向きになるようにしていくんです。そうすると、力の養分が上に向かって上がっていくようになって一つかげさま一つの実が多く甘く育つんです。お陰様で消費者の皆様に喜んでいただいています。"}, {"k": "q", "t": "農家の人は何について話していますか?"}, {"k": "text", "t": "1梨を作るようになったきっかけ2品種ごとの梨の特徴3梨を栽培しながら感じる楽しさ4いい梨を作るための栽培の工夫JLPT・N1・07/2023"}]}, {"head": "市民講座で気象予報士の人が話しています。", "lines": [{"k": "text", "t": "日本初の天気予報が発表されたのは、1884年、現在に比べると、当時の観測データが限られたもので、予報もかなり大まかなものでした。日本の天気予報が進化したのは1950年以降で、54年には気象レーダーが初めて日本でも完成し、59年にはコンピューターが導入されました。1970年代になると、日本全国約1300カ所に降水量を計測する機器が設置され、気象衛星を打ち上げられて、多くのデータが集まるようになりました。今ではスーパーコンピュータが活躍し、予報の精度も上がりました。それらデータに加えて、経験豊かな予報士が過去に得た知識を踏まえ、予報を出しています。"}, {"k": "q", "t": "気象予報士は主に何について話していますか?"}, {"k": "text", "t": "1天気予報の重要性2天気予報の発展3天気予報の活用4天気予報に必要な知識と経験"}]}], "2023-12": [{"head": "ラジオで男の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "レストランではよくBGMがかかっていますよね。BGMは店の雰囲気を演出するという役割を果たしてるだけじゃないんです。ある実験では異なるジャンルのBGMが流れる部屋で客に様々な料理を食べてもらったところ、スパイスの効いた料理はジャズよりロックの方が辛く感じる。テンポが速い音楽の中で食べると酸味を強く感じるなど、BGMによって料理の味の感じ方が変わるという結果が出ました。また、和食の場合、ジャズを流すとおいしく感じられるという報告もあるそうです。レストランに行った時、どんな曲がかかっているのか気にかけてみるのも面白いかもしれませんね。男の人は何について話していますか。正解:1"}, {"k": "ch", "t": "1.音楽が味覚に与える影響"}, {"k": "ch", "t": "2.料理をおいしく感じる音楽の音量"}, {"k": "ch", "t": "3.どんな料理にも合う音楽"}, {"k": "ch", "t": "4.レストランで客に好まれる音楽"}]}, {"head": "テレビでアナウンサーの女の人と専門家がについて話しています。", "lines": [{"k": "spk", "s": "女", "t": "今日は私たちの身近にいる昆虫、アリについてお話を伺います。"}, {"k": "spk", "s": "男", "t": "えー、アリの巣の中には大量のアリが住んでいます。アリというと朝から晩までせっせと働く、働きアリをイメージされる方が多いと思いますが、実はアリがみんな働き者というわけではないんです。"}, {"k": "spk", "s": "女", "t": "とおっしゃいますと?"}, {"k": "spk", "s": "男", "t": "本来は巣の中で集団で子供を育て、エサを運んだり、敵の侵入に備えたりしているんですが、それは多くの働きアリのことで、中には働かずにエサだけ食べているアリもいるんです。"}, {"k": "spk", "s": "女", "t": "はぁ、そんなアリもいるんですか。"}, {"k": "spk", "s": "男", "t": "ええ、ところがですね、アリの巣から働きアリを除去すると、怠けていたアリが働きアリになって働き出すんです。彼らがいるおかげで働いているアリが大量に死ぬようなことが起こっても、アリの巣の機能が停止せずにいられるんです。"}, {"k": "spk", "s": "女", "t": "なるほど。"}, {"k": "spk", "s": "男", "t": "働かないアリがいるのにも意味があるんですね。専門家は何について話していますか。正解:3"}, {"k": "ch", "t": "1.アリが働かなくなるタイミング"}, {"k": "ch", "t": "2.働くアリの割合が増える理由"}, {"k": "ch", "t": "3.アリが巣の機能を維持する仕組み"}, {"k": "ch", "t": "4.働くアリと働かないアリの強さの違い"}]}, {"head": "テレビでレポーターが話しています。", "lines": [{"k": "spk", "s": "男", "t": "私は今、文房具の展示会会場に来ています。会場の特設コーナーに並んでいる色とりどりの紙、触った感じ、ザラっとしていて独特の風合いがあるんです。この紙、原料は何だと思いますか?野菜をすり潰してその繊維で作られたものなんです。野菜は規格外などの理由で約20%が廃棄処分となるそうです。そこで桜市で食品廃棄の削減に取り組むNGOと製紙会社、地元の農家さんがこれを何とか使えないかということで共同で商品化されたそうです。当初はいろいろとうまくいかないこともあったそうですが、試行錯誤を重ね、今回の商品化に至ったということです。レポーターは何について話していますか。正解:3"}, {"k": "ch", "t": "1.原料によって紙の色が異なる理由"}, {"k": "ch", "t": "2.紙をリサイクルする方法"}, {"k": "ch", "t": "3.廃棄野菜を利用した紙作り"}, {"k": "ch", "t": "4.野菜が規格外となる基準"}]}, {"head": "講演会で宇宙科学の専門家が話しています。", "lines": [{"k": "text", "t": "現在、気象衛星や通信衛星など、たくさんの人工衛星が地球の周りをまわっていますが、役目を終えた人工衛星やロケットの機体の一部なども地球の周りをたくさん漂っています。これらは人工衛星に衝突する事故も起きていて、人類の宇宙での活動に支障をきたすことが今後ますます危惧されます。宇宙というと人工衛星やロケットの打ち上げが注目されがちですが、地球の周りにあるこれらのものをいかに除去するか、ということも近年の課題となっています。専門家は何について話していますか。正解:4"}, {"k": "ch", "t": "1.人工衛星の役割"}, {"k": "ch", "t": "2.宇宙で起きる事故の頻度"}, {"k": "ch", "t": "3.ロケット開発技術の進歩"}, {"k": "ch", "t": "4.宇宙に漂う不要な物体への懸念"}]}, {"head": "テレビのニュース番組でアナウンサーが話しています。", "lines": [{"k": "spk", "s": "男", "t": "過疎化による児童数の減少で3年前に閉校した青村の小学校の校舎が先月、宿泊施設としてよみがえりました。建物を改修して温泉施設も造り、人気となっています。かつての教室には畳が入れられ、研修や会議に使用できる部屋も備えられています。運営を担う村は、「宿泊だけでなく村にある滝や渓谷へハイキングに来た人の休憩場所など、多様な目的で利用してほしい、地元住民と外部から訪れた人との交流拠点としての役割も期待している」と話しています。また、村では都会からの移住者を受け入れる政策も進める予定で、この施設の利用を通して移住希望者が増えればと願っているとのことです。アナウンサーはこの村の何について話していますか。正解:2"}, {"k": "ch", "t": "1.小学校の新しい校舎の建設"}, {"k": "ch", "t": "2.廃止された学校の校舎の活用"}, {"k": "ch", "t": "3.住民と観光客の交流イベント"}, {"k": "ch", "t": "4.移住の希望者が増えた理由"}]}], "2024-07": [{"head": "ラジオでアナウンサーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "大学生の学生寮に注目が再び集まっています。40年前は学生寮に入る人が大半でしたが、だんだんとルールが厳しく、息苦しいという理由で避けられ、一人暮らしのアパートの人気が高まりました。しかし、最近の寮は楽器練習用の部屋など共用施設を充実させたりと魅力的になっています。寮に入りたいという人が定員を超え、抽選までしている寮もあります。また、食事付き、職員が常駐の寮もあり、初めて一人暮らしをする学生にとってはいつも頼れる大人がいるという安全面の利点、食事の提供があることも安心感に繋がっているようですアナウンサーは主に何について話していますか。1学生寮のルールの変化2学生寮の人気が復活した理由3一人暮らしの学生が心配していること4一人暮らしの学生に人気がある食事"}]}, {"head": "ビジネスセミナーで社長が話しています。", "lines": [{"k": "spk", "s": "女", "t": "えー、私は種を蒔くという言葉が好きです。「大きな花を咲かせたいと思うならまず、種を蒔くことだ。そして芽が出るまで待っことも楽しめ」と会社経営をしていた亡き父が教えてくれました。普段は無ロでほとんど話さない人だったんですが、私が最初の事業でつまずいた時、そう声をかけてくれました。私は学生時代からいくつもの事業を手掛けていますが、リスクもありますし、うまくいかないこともあります。そんな時、いつも父の言葉に励まされてきました。これからも新たな土地を耕し、種を蒔き続けていこうと思っています。"}, {"k": "q", "t": "社長は何について話していますか。"}, {"k": "text", "t": "1自分にとっての心の支え2父から引き継いだ事業3起業する時のリスク4会社を始めたきっかけ"}]}, {"head": "ラジオでカーテンのメーカーの人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "日光が部屋を入るのを遮ったり、外から見えないようにするためにカーテンは欠かせませんよね。日本では古くから安く手軽に手に入れられる木や紙で作ったふすまや障子をカーテンのように用いてきました。カーテンが日本で広く使われるようになったのは、西洋的なライフスタイルが始まった昭和30年代以降です。時の日本は急激な経済成長に伴って、団地やアパートなどが次々と建てられるようになり、洋風にデザインされた住まいが一気に増えたからです。それ以降、カーテンは私たちの生活に浸透しました。"}, {"k": "q", "t": "カーテンのメーカーの人は何について話していますか。"}, {"k": "text", "t": "1カーテンの素材の発展2日本らしいカーテンのデサイン3カーテンの値段の変化4日本におけるカーテンの普及"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "私にとって桜町は第二の故郷です。私の小説の舞台としてこの町の商店街やお寺、坂道をしばしば登場させていますが、実は私がここで過ごしたのは学生時代の4年にすぎません。親元を離れて暮らした4年間は実に濃く、青春そのものでした。思い出深い場所が数えきれほどあります10代、20代を主人公に物語を書く時、その背景には自然とこの町が存在しているんです作家は何について話していますか。1自分にとって特別な町2学生時代の経験3自分が生まれた故郷4桜町の美しさ"}]}, {"head": "科学館で恐竜の研究者が話しています。", "lines": [{"k": "spk", "s": "女", "t": "10年前、みどり市で恐竜の化石が発見されましたが、「この恐竜が何を食べていたのか」ということはこれまでわかっていませんでした。仮に植物を食べる植物食だとして、どういう植物を食べていたのか、私たち研究グループはこの恐竜の歯の化石の表面の微かな凹凸を最新の技術で分析しました。そして、爬虫類の歯と比べたのです。例えば、爬虫類の動物に虫、植物などを食べさせた時、歯に付く細かい傷は食べたものによって異なります。その違いを分析し、この恐竜の歯の化石の表面に当てはめて考えることで、恐竜がどういったものを食べていたのかを具体的に推測できるようになったのです研究者はこの恐竜の何について話していますか。1食べ物の食べ方2食事をしていた場所の特徴3生きていた時代の環境4食べていたものの調査方法"}]}], "2024-12": [{"head": "親子向けのクラシックコンサートの会場でオーケストラの指揮者が話しています。", "lines": [{"k": "spk", "s": "男", "t": "緑オーケストラの指揮者の山田です。オーケストラにはいろいろな楽器がありますが、指揮者は指揮棒1本だけです。リズムを取るぐらいで簡単そうに見えるかもしれませんが、そんなことはありません。というのは、曲に対して持つイメージって人によってバラバラなんですよね。同じ曲の楽譜を見ても山場がどこにあるかとか、この部分は何を表しているのかなどの解釈が違います。指揮者は自分なりの解釈をオーケストラの団員に伝えて、演奏をまとめあげるんです。それだけでなく、団員との信頼関係を築き、演奏者が持っ表現力を最大限に引き出すことも求められるんです。"}, {"k": "q", "t": "指揮者は何について話していますか。"}, {"k": "text", "t": "1楽器による演奏法の違い2演奏会の楽しみ方3団員の能力を信じることの大切さ4指揮者の役割"}]}, {"head": "テレビでアナウンサーの男の人が商店街の代表の人にインタビューをしています。", "lines": [{"k": "spk", "s": "男", "t": "地方の商店街が衰退していく傾向がある中てこの桜通り商店街はたくさんのお客様で賑わっていますね"}, {"k": "spk", "s": "女", "t": "ありがとうございます。一時はお客様が減って、商店街全体が寂しい時期もありました。それで3年ほど前から若い店主たちを中心にお客様に喜んでもらえるような商店街全体のイベントを企画しているんです。"}, {"k": "spk", "s": "男", "t": "そうなんですか。どんなイベントをやっていらっしやるんですか~"}, {"k": "spk", "s": "女", "t": "例えば、学生デーを設けて、その日は全店舗で学生割引を行ったり、七夕など季節ごとにイべントを開催したりしています。"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "他にも飲食店で写真を撮りたくなるような盛り付けを工夫したメニューを開発し、それをインターネットで発信したりしています。おかげさまで近隣の方だけでなく、ネットの記事を見た遠方の方も来てくださっています。"}, {"k": "q", "t": "商店街の代表の人は何について話していますか。"}, {"k": "text", "t": "1商店街の店の入れ替わり2商店街の活性化の取り組み3商店街で新たに取り組むべき課題4商店街で新人気があるイベント"}]}, {"head": "テレビの動物番組で専門家がゴリラについて話しています。", "lines": [{"k": "spk", "s": "女", "t": "私はゴリラの生態を研究しています。私の研究はジャングルで野生のゴリラの群れを追いかけ、観察することから始まります。ただ、警戒しているゴリラに近づいて殴られたりすると危険ですから少しずっ距離を縮めるんです。ゴリラは他の動物を見ると相手を知ろうと近づきますが、相手が怖がって下を向いたり、目を反らしたりすると相手を敵だと認識して威嚇してきます。なので我々も怯まずに目を合わせます。そしてゴリラの行為を真似してゴロっと横になったり、食べたりしているうちにゴリラは我々には敵意がないと認識してくれ、近づくことを許すようになります。"}, {"k": "q", "t": "専門家は何について話していますか。"}, {"k": "text", "t": "1ゴリラが敵を攻撃する方法2ゴリラの記憶力の良さ3ゴリラとの信頼関係を築く方法4ゴリラの研究を始めた理由"}]}, {"head": "ラジオである島の医師が話しています。", "lines": [{"k": "spk", "s": "男", "t": "私は都会の大学病院で10年勤務し、3年前に小さな島の診療所に赴任しました。こでは様々病気や怪我に対応する必要があり、医師としての総合的な技量が高められると感じています。島は患者さんとの距離が近く、診療所以外でも患者さんによく会います。薬や治療の効果について直接聞けたり、患者さんと一緒に病気に向き合っているという実感があって手応えが感じられます。また、生活習慣について島の人たちに積極的にアドバイスするなど地域の予防医療に貢献できることにも魅力を感じています。"}, {"k": "q", "t": "この島の医師は何について話していますか。"}, {"k": "text", "t": "1この島の医師になったきっかけ2この島の医師としてのやりがい3この島の医療の困難な点4この島の生活習慣と病気の関係"}]}, {"head": "市民講座で発酵食品について講師が話しています。", "lines": [{"k": "spk", "s": "女", "t": "皆さん、ヨーグルトやチーズの発酵食品は好きですか~発酵食品はいろいろな実験を通して健康効果が実証されていますが、加熱すると有益な菌の働きが損なわれるので、できるだけそのまま食べることをお勧めします。毎日継続して摂取すると、より効果が期待できます。それから食べ物の組み合わせにも注意を払いたいですね。パナナやごぼうのように食物繊維が含まれているものと一緒に摂ると菌の活動が活発になるんです。"}, {"k": "q", "t": "冓師は何について話していますか。"}, {"k": "text", "t": "1発酵食品に含まれる成分2発酵食品を使った料理3発酵食品が好まれる理由4発酵食品の効果的な食べ方"}]}], "2025-07": [{"head": "自然公園の入り口でガイドが話をしています。", "lines": [{"k": "text", "t": "こんにちは、ガイドの森田です。よろしくお願いします。えー、この自然公園では珍しい動物や植物に出会うことができます。特に冬の今の時期は木々の葉が落ちているので、野鳥を探しやすいです。散策しながら、野生の小鳥たちのさえずりに耳を傾けてみましょう。これから雑木林の中に整備された遊歩道を進みますが、双眼鏡がなくても肉眼で可愛い姿を見つけられます。種類を見分けるには羽や嘴がそれぞれ特徴的なので、様子を眺めてみてください。運が良ければ保護の対象になっている貴重な野鳥にも巡り会えるかもしれません。"}, {"k": "q", "t": "ガイドは何かについて話していますか。"}, {"k": "text", "t": "野鳥の観察の楽しみ方自然保険で育つ植物自然公園を歩く時の注意点野鳥の保護の必要性"}]}, {"head": "市民講座で講師が空飛ぶ車について話しています。", "lines": [{"k": "text", "t": "空飛ぶ車は新たな交通手段として期待されており、開発が進んでいます。デザインも各社、競争が加速しています。ただ、都市部では墜落したら大きな被害につながると心配する人々もいます。しかし、一部の地方では鉄道もなくなり、交通手段の確保が問題になっていて、空飛ぶ車を求める声が多いんです。空飛ぶ車の普及で点在する民家と医療機関や商業施設を結ぶことができれば、ずっと便利になるでしょう。"}, {"k": "q", "t": "講師は主に空飛ぶ車の何について話していますか。"}, {"k": "text", "t": "デザインの特徴技術改善の難しさ重大な事故の危険性地方での活用への期待"}]}, {"head": "市民講座で料理研究家が話しています。", "lines": [{"k": "text", "t": "醤油の主な原料は大豆と小麦、それから塩です。原料の配合、割合、作り方や熟成期間は作られる地方によって異なります。例えば、日本の南の地方では甘味料が入っている甘めのものが作られ、西の方では塩分が濃いしょっぱいものが作られています。それぞれの地方の風土や嗜好などに深く根ざし、様々な味が生まれます。どこの醤油を用いるかで、料理の味も様々に変わります。いろんな醤油を試してみてください。"}, {"k": "q", "t": "料理研究家は何について話していますか。"}, {"k": "text", "t": "醤油の作り方醤油の製造に適した地方地方によって異なる醤油の味醤油の上手な選び方"}]}, {"head": "ラジオでアナウンサーが家具を作る職人にインタビューしています。", "lines": [{"k": "text", "t": "今日は家具職人の山下さんにお話を伺います。山下です。私は家具を手作りで作っています。木材は時間が経つにつれて変化するので、木の家具は年月が経つと色や質感にいい味が出てくるんです。私は木材それぞれの特徴を常々勉強し、木材の変化を見越して、最適なものを選ぶことが大切だと思っています。数十年後の色に深みが増し、木目が様々な美しい模様に変化する姿をイメージし、一つ一つ作っています。"}, {"k": "q", "t": "家具を作る職人は何について話していますか。"}, {"k": "text", "t": "家具職人としてのこだわり家具に使用される木の種類木の家具の手入れの仕方家具職人の大変さ"}]}, {"head": "講演会で専門家が話しています。", "lines": [{"k": "text", "t": "公衆電話の数は携帯電話の普及に伴い、減少する一方です。このまますっかり消えてしまうのでしょうか?実は公衆電話は一定区域に一つは設置するよう、国の規則で決められています。というのも公衆電話は災害時の最も有効な通信手段だからです。停電時であっても使用が可能で、電話回線が混み合っても、通信制限の対象になりません。このようなことから一定数設置されています。"}, {"k": "q", "t": "専門家は何について話していますか。"}, {"k": "text", "t": "今後の公衆電話に必要な機能災害時の公衆電話をかけ方公衆電話を利用する時の注意点公衆電話が完全に無くならない理由"}]}], "2025-12": [{"head": "日本茶の専門店で男の人がお茶の説明をしています。", "lines": [{"k": "spk", "s": "男", "t": "近年、海外でも人気がある日本茶ですが、お茶の葉は日本各地で栽培されています。大きく分けると、平地で育てられたものと山間部で育てられたものがあります。平地は遮るものがないので、日の光を長時間浴びますからお茶の葉がよく育ち、葉っぱに厚みが出て渋みが増すんです。平地に比べて日の当たる時間が短いのが山と山に挟まれた山間部です。一日の気温差が大きく、それがお茶の葉の甘みと香りを引き出すことがわかっています。どうぞ、いろいろな種類のお茶を試してみてください。"}, {"k": "q", "t": "問い男の人は何について話していますか。"}, {"k": "text", "t": "栽培地の地形によるお茶の味の違いお茶の葉を育てるのが難しい気候海外で人気がある日本茶の種類香りを引き出す、お茶の入れ方"}]}, {"head": "地域のテレビ番組でレポーターが話しています。", "lines": [{"k": "spk", "s": "女", "t": "今、私がいるのは桜川の西にある竹林です。こちらの竹の林、数年前まで手入れされず、竹が密集して昼でも薄暗い雰囲気でした。そこで地元の有志が協力して、竹を切って、地元の見どころとなるよう整備したんです。まず、林を整備する費用を得るために切っどじょうかいりょうざいた竹を土壌改良剤やかごなどの竹細工の製品にして販売しました。その売り上げで遊とうこう歩道を設置し、イベントを行ったり、夜間にライトアップしたりして、SNSにも投稿しげんそうてきました。幻想的な風景が受け、今では海外からも多くの人が訪れるようになったとのことです。"}, {"k": "q", "t": "問いレポーターはこの林の何について話していますか。"}, {"k": "text", "t": "環境に負担をかけない開発整備に必要な条件竹を使った新製品の魅力観光地化されるまでの過程"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "text", "t": "わき"}, {"k": "spk", "s": "女", "t": "北山駅の改札口の脇に設置されている犬型ロボットが話題になっています。人が触ると、ないぞう頭に埋め込まれたセンサーで触った人の力の強さを読み取ると同時に内蔵されたカメラとマイクで声や表情を認識します。人工知能が受け取った情報を分析し、触った人の気持ちを推測した上で、それに合うように鳴き声やしっぽの振り方を決めます。そしてうれしい、驚いたなどの感情を表現してくれます。皆さんも1度行って触ってみてください。"}, {"k": "q", "t": "問いアナウンサーは北山駅にある犬型のロボットの何について話していますか。"}, {"k": "text", "t": "触った人に反応を返す仕組み駅に設置されたきっかけ人の感情表現を真似する能力駅の利用者を見守る機能"}]}, {"head": "起業を考えている人向けのセミナーで男の人が話しています。", "lines": [{"k": "text", "t": "わかな"}, {"k": "spk", "s": "男", "t": "私は東京から車で3時間ほどの若菜市で起業しました。地方都市って事務所を構える場合でも家賃や初期費用がかなり抑えられるんですよ。低コストだから失敗を恐れずにやってみようという気持ちで挑戦できたんです。自治体によっては補助金が出るところもありますよ。それに競合する相手が少ない分、地元の会社にも覚えてもらえて、共同で仕事をする機会が増えるんです。また地方には特有の人脈というか、ネットワークがありますよね。これも起業する上ではプラスに働くことが多いんです。皆さんも地方を拠点とすることをぜひ検討してみてください。"}, {"k": "q", "t": "問い男の人は何について話していますか。"}, {"k": "text", "t": "地方で起業するための手続き地方での起業に適した仕事の分野地元の会社との協力の仕方地方で起業するメリット"}]}, {"head": "ラジオで心理カウンセラーが話しています。", "lines": [{"k": "spk", "s": "女", "t": "日常生活の中で怒りを感じることってありますよね。そんな時は深呼吸するとか数字を数えるのが効果的だと言われています。先日、ある研究グループによって怒りを感じた時の行動について実験が行われました。実験では参加者に怒りを感じさせる状況を作り、その後で全員にどのように怒りを感じたかを紙に書いてもらいました。書いた紙をそのまま持っていた人たちは怒りの程度があまり変わらなかったそうです。一方、紙を丸めて捨てたり、シュレッダーで裁断した人たちは怒りが軽減したそうです。皆さんも参考にしてみてくださいね。"}, {"k": "q", "t": "問い心理カウンセラーは何について話していますか。"}, {"k": "text", "t": "怒りの気持ちの伝え方怒りを抑えることの大切さ感じた怒りに対処する方法怒りを感じた時にとりがちな行動"}]}], "2026-07": [{"head": "ラジオでアナウンサーが女の人にインタビューしています。", "lines": [{"k": "spk", "s": "男", "t": "株式会社あおい、代表の野田さんにお話を伺います。"}, {"k": "spk", "s": "女", "t": "着なくなった服は捨ててしまうという方もいらっしゃると思いますが、私は古い衣類、特に綿の布を紙に作り変える技術に着目し、昨年起業いたしました。綿からは普通の紙よりも水をはじく強い紙ができるので、清涼飲料水のラベルやコースター、ゴミ箱、野外に展示するアート作品に使われています。このような技術があることをより多くの方に知っていただくために、事業を起こすに至りました。材料にできるものって実はたくさんあるんだ、と気づいていただきたい。人々の意識を変えられるように努めます。"}, {"k": "q", "t": "女の人は何について話していますか？"}, {"k": "ch", "t": "1.会社を立ち上げた理由"}, {"k": "ch", "t": "2.洋服の素材へのこだわり"}, {"k": "ch", "t": "3.布をリサイクルする為の条件"}, {"k": "ch", "t": "4.ファッション業界の課題"}]}, {"head": "テレビでアナウンサーが話しています。", "lines": [{"k": "text", "t": "自動運転の無人タクシーについて、各自動車メーカーが開発に力を入れています。ドライバー不足を解消するアイディアとして、大きな期待が寄せられる一方、課題も見られます。すでに試験的に導入されている地域からは急な停止で交通の妨げになったり、事故を起こしたりといった例も報告されています。その他法律についても整える必要があり、安心して利用できるようになるまでにはもう少し時間がかかりそうです。"}, {"k": "q", "t": "アナウンサーは無人タクシーの何について話していますか？"}, {"k": "ch", "t": "1.安全な乗り方"}, {"k": "ch", "t": "2.開発のプロセス"}, {"k": "ch", "t": "3.実用化における問題点"}, {"k": "ch", "t": "4.自動運転の仕組み"}]}, {"head": "講演会で栄養士が話しています。", "lines": [{"k": "text", "t": "野菜は毎日の食事に欠かせない食材です。茹でたり、油で炒めたりして、熱を加えて食べる温野菜は調理することで、かさが減り、一度にたくさん食べられる上に消化しやすいです。ただ、野菜を加熱すると、ビタミンCやビタミンB群ミネラルが破壊されたり流出したりしてしまいます。一方、サラダなどで食べる生野菜は豊富なビタミンや食物繊維をそのまま取り入れることができますが、温野菜に比べ、消化吸収に時間がかかります。胃腸が弱っている時に食べ過ぎると、体に負担をかけてしまいます。温野菜と生野菜、上手に組み合わせて食べるのが理想的ですね。"}, {"k": "q", "t": "栄養士は野菜の何について話していますか？"}, {"k": "ch", "t": "1.美味しく食べる為の工夫"}, {"k": "ch", "t": "2.食べる量と健康の関係"}, {"k": "ch", "t": "3.たくさん食べた方がいいわけ"}, {"k": "ch", "t": "4.調理法によって異なる利点と欠点"}]}, {"head": "大学で先生が話しています。", "lines": [{"k": "text", "t": "台風は夏から秋にかけて多く発生します。台風が通過すると、強い風で海の水が上下にかき混ぜられるので、海の表面近くの温度が高くなりすぎるのを抑えられます。この時、海水に含まれる酸素や栄養分がよく混ざり、海の生物が住みやすい環境になります。また、台風が通る場所にはたくさんの雨が降るため、農業用や生活用など資源としての水が得られます。"}, {"k": "q", "t": "先生は何について話していますか？"}, {"k": "ch", "t": "1.台風による恩恵"}, {"k": "ch", "t": "2.台風の進路"}, {"k": "ch", "t": "3.台風から環境を守る方法"}, {"k": "ch", "t": "4.台風が発生する原因"}]}, {"head": "市民講座で専門家が話しています。", "lines": [{"k": "text", "t": "恐竜の化石というと、骨や歯をイメージしますが、地面を歩いていた場所にできた足跡も化石として残っています。それを見ると恐竜の大まかな種類が識別できます。また足跡の縦の長さからその跡をつけた恐竜の腰の高さが把握でき、歩幅から歩行の速度を推定することもできます。他にも群れで生活していたかどうかや、怪我をしていたかどうかなどを知る手がかりにもなります。骨や歯の化石だけからは定かにできない多くのことを語りかけてくれます。"}, {"k": "q", "t": "専門家は何について話していますか？"}, {"k": "ch", "t": "1.最近発見された恐竜の化石"}, {"k": "ch", "t": "2.恐竜の骨や歯の研究成果"}, {"k": "ch", "t": "3.恐竜の化石が見つかりやすい場所"}, {"k": "ch", "t": "4.恐竜の足跡からわかること"}]}]};
